window.ARTICLE_BODIES={"שיא-אישי-חדש-למאור-טיורי-בחצי-מרתון-ולנסיה-1-10-30-שעות":{"b":[{"t":"p","x":"**הרצה האולימפית הישראלית רשמה הישג אישי חדש באחד ממרוצי הכביש הבולטים בעולם, והמשיכה לשפר את הישגיה במרחק חצי המרתון.**"},{"t":"img","src":"bf0bf7_244a1eb776084a59a8a5c4aa06c6c3c1~mv2.jpeg","cap":"מאור טיורי במירוץ(צילום: Cluj 10K )"},{"t":"p","x":"מאור טיורי רשמה שיא אישי חדש בחצי מרתון ולנסיה שבספרד, כשחצתה את קו הסיום בזמן של **1:10:30 שעות**."},{"t":"p","x":"עבור טיורי, מהאתלטיות הבולטות בישראל בריצות למרחקים ארוכים, מדובר בהישג משמעותי ובשיפור נוסף ביכולתה התחרותית. חצי מרתון ולנסיה מושך מדי שנה רצות ורצים ברמה בינלאומית גבוהה, בזכות המסלול המהיר והאווירה התחרותית."},{"t":"p","x":"טיורי, שייצגה את ישראל בשלוש מהדורות של המשחקים האולימפיים — ריו 2016, טוקיו 2020 ופריז 2024 - ממשיכה לבסס את מעמדה באתלטיקה הישראלית ולסמן יעדים חדשים בקריירה."},{"t":"p","x":"השיא החדש בוולנסיה הוא ציון דרך נוסף בדרך הארוכה של ספורטאית הישגית, שממשיכה להציב לעצמה מטרות ולחתור לשיפור מתמיד."},{"t":"p","x":"**‏WSP‎ גאה בהישגיהן של הספורטאיות הישראליות וממשיכה לתת במה לסיפורים שמאחורי ההצלחות.**"}]},"המסע-של-שרה-מייסנברג":{"b":[{"t":"h2","x":"איך שחקנית לקרוס אמריקאית מצאה בישראל בית, קהילה ושליחות."},{"t":"p","x":"לפעמים סיפור ספורט מתחיל במדליה ולפעמים בחלום אולימפי."},{"t":"p","x":"הסיפור של שרה מתחיל דווקא במקום אחר לגמרי."},{"t":"p","x":"באנרגיה שלא נתנה לה מנוחה."},{"t":"img","src":"8f604f_958277fbc28b475d8bf3ae63af16c510~mv2.jpg","cap":"שרה מייסנברג בפעולה במשחק לקרוס (צילום: ג׳ודי אפלבאום)"},{"t":"p","x":"כילדה היא הרגישה שמשהו בתוכה עובד בעוצמה גבוהה יותר. רק שנים אחר כך היא הבינה למה."},{"t":"p","x":"“יש לי חרדה,” היא מספרת היום בכנות. “רק לפני שנתיים גיליתי שזה מה שיש לי. אבל כשהייתי צעירה לא ידעתי לתת לזה שם. הספורט היה הדרך שלי לשחרר את כל האנרגיה שיש לי בגוף.”"},{"t":"p","x":"היא הייתה ביישנית, לא ילדה שממהרת להיות במרכז."},{"t":"p","x":"אבל על המגרש קרה משהו אחר."},{"t":"p","x":"“דרך הספורט למדתי להיפתח. לדבר עם אנשים. להיות חלק מקבוצה.”"},{"t":"p","x":"וכך, בלי תוכנית מסודרת הספורט הפך לשפה שלה בעולם."},{"t":"h3","x":"הדרך המפתיעה לנבחרת ישראל"},{"t":"p","x":"שרה גדלה בארצות הברית בבית שבו תנועה הייתה חלק מהחיים. אביה רץ ושיחק רוגבי, וההורים עודדו אותה לעשות ספורט מגיל צעיר."},{"t":"p","x":"אבל למרות האהבה הגדולה היא לא באמת חשבה שאפשר לבנות מזה חיים."},{"t":"p","x":"היא למדה ביולוגיה ובריאות הציבור, המשיכה לתואר נוסף, ואפילו עבדה במערכת הבריאות."},{"t":"p","x":"“כל החיים אהבתי ספורט,” היא אומרת, “אבל לא ידעתי שיש דרך לעבוד בזה.”"},{"t":"p","x":"ואז הגיע טלפון ששינה את המסלול."},{"t":"p","x":"בשנת 2012 התחילו להקים את נבחרת ישראל לנשים בלקרוס – ענף פופולרי בארצות הברית, אך כמעט לא קיים בארץ. המטרה הייתה למצוא שחקניות יהודיות מרחבי העולם."},{"t":"p","x":"שרה הצטרפה ברצון."},{"t":"p","x":"שנה לאחר מכן כבר מצאה את עצמה עושה עלייה רק כדי לשחק."},{"t":"p","x":"היא הגיעה לישראל לשבוע אחד בלבד, קיבלה תעודת זהות, התאמנה עם הנבחרת — וטסה לאליפות העולם בקנדה."},{"t":"p","x":"הנבחרת סיימה במקום התשיעי מתוך כ-17 מדינות. עבור שרה התוצאה לא הייתה הדבר החשוב באמת."},{"t":"p","x":"זו הייתה ההתחלה של קשר עמוק עם הארץ."},{"t":"img","src":"8f604f_c287caacdab540d2b1fa12b1760a9562~mv2.jpeg","cap":"שרה מייסנברג במהלך משחק פוטבול אמריקאי (צילום: Rachel Wolf)"},{"t":"h3","x":"מה שקרה באשקלון שינה את הכל"},{"t":"p","x":"אחרי האליפות היא חזרה לארצות הברית כדי לסיים את הלימודים."},{"t":"p","x":"אבל משהו כבר השתנה."},{"t":"p","x":"ב-2015 היא חזרה לישראל לשלושה חודשים של אימונים עם הנבחרת כל הקבוצה עברה לגור באשקלון."},{"t":"p","x":"הימים התחילו באימונים והמשיכו בהדרכת ילדים ונערות בספורט."},{"t":"p","x":"שם קרה רגע שהפך את הכל לברור."},{"t":"p","x":"“זו הייתה הפעם הראשונה שאימנתי,” היא נזכרת. “והיה לי כל כך הרבה כיף. פשוט הבנתי כמה אני אוהבת להיות בעולם הזה.”"},{"t":"p","x":"כשהיא חזרה שוב לארצות הברית כדי לעבוד בבית חולים כאחות ההחלטה כבר התבשלה בתוכה."},{"t":"p","x":"היא לא רצתה להישאר שם. היא חזרה לישראל."},{"t":"p","x":"לתמיד."},{"t":"h3","x":"מדינה קטנה - השפעה גדולה"},{"t":"p","x":"ההחלטה להשאר בארץ אולי נשמעת מוזרה."},{"t":"p","x":"בארצות הברית, הספורט מפותח יותר.יש יותר כסף, יותר ליגות, יותר הזדמנויות."},{"t":"p","x":"אבל דווקא בישראל שרה מצאה משהו אחר."},{"t":"p","x":"משמעות."},{"t":"p","x":"“במדינה קטנה אני יכולה לעשות יותר אימפקט,” היא אומרת. “עם הניסיון שלי בספורט אני יכולה להשפיע כאן על יותר אנשים מאשר בארצות הברית.”"},{"t":"p","x":"היא עברה בין ערים – חיפה, ירושלים, באר שבע, אשקלון – אימנה קבוצות, פיתחה ענפים, ואפילו הצטרפה לנבחרת ישראל בפוטבול אמריקאי."},{"t":"p","x":"הספורט הפך לגשר בין תרבויות."},{"t":"p","x":"ובסוף גם לבית."},{"t":"h3","x":"הרגע שבו הבינה למה ספורט באמת חשוב"},{"t":"p","x":"אחד הרגעים שנשארו איתה במיוחד היה באליפות העולם בלקרוס."},{"t":"p","x":"נבחרת ישראל שבה שרה שימשה כעוזרת מאמנת ומנהלת של הקבוצה, שיחקה מול נבבחרת קניה. השחקניות הקנייתיות הגיעו בלי נעלי פקקים מקצועיות."},{"t":"p","x":"שחקניות הנבחרת הישראלית החליטו לעשות משהו קטן אבל גדול. הן אספו כסף וקנו להן נעלי משחק."},{"t":"p","x":"“זה היה רגע מדהים,” היא מספרת בהתלהבות.“וזה בדיוק למה אני אוהבת ספורט.”"},{"t":"p","x":"לא רק תוצאות אלא אנשים."},{"t":"p","x":"קהילה."},{"t":"h3","x":"לפעמים הכל מתערער גם עבור ספורטאית"},{"t":"p","x":"דווקא אחרי שנים של ספורט ברמה גבוהה הגיע הרגע שבו הכול נעצר."},{"t":"p","x":"לאחר שפרשה מלקרוס תחרותי שרה מצאה את עצמה בתקופה לא פשוטה."},{"t":"p","x":"“פתאום הרגשתי שאיבדתי את הזהות שלי,” היא מספרת. “כל החיים שלי הייתי ספורטאית ברמה גבוהה. זה היה הכול – הקהילה שלי, העבודה שלי, החיים שלי. ואז זה נגמר. שאלתי את עצמי: מה עכשיו?”"},{"t":"p","x":"היא טיילה קצת, חזרה לישראל וחיפשה עבודה עם התחושה שתצטרך להתחיל את כל מחדש."},{"t":"p","x":"“אי אפשר להיות ספורטאית מקצועית לנצח. מגיע רגע שבו צריך לפרוש. הבנתי שאני צריכה לחשוב מי אני מעבר לספורט.”"},{"t":"p","x":"ואז הגיעה התובנה. “הבנתי שהזהות שלי היא לא רק הספורט. הזהות שלי היא מישהי שעובדת קשה וכל הזמן מנסה להשתפר.. השאלה הייתה איך לקחת את הערכים האלה ולהעביר אותם למשהו חדש.”"},{"t":"p","x":"התשובה הגיעה כשהגיעה למרכז הספורט ספיבק."},{"t":"p","x":"“ברגע שהגעתי לכאן ידעתי שזה המקום שלי.”"},{"t":"h3","x":"הרעיון שנולד באילת"},{"t":"p","x":"גם היום שרה לא מפסיקה לחשוב איך להרחיב את גבולות הספורט."},{"t":"p","x":"לפני כמה שנים היא השתתפה בתחרות חצי איש ברזל באילת."},{"t":"p","x":"האירוע, לדבריה, הוא אחד מאירועי הספורט המרגשים בישראל."},{"t":"p","x":"אבל בזמן שהייתה שם עלה לה רעיון."},{"t":"p","x":"ביום שישי מתקיימת תחרות השליחים של הטריאתלון ולמחרת תחרות שחייה בים."},{"t":"p","x":"שרה חשבה על הספורטאים שהיא עובדת איתם במרכז ספיבק. שחיינים עם מוגבלות שמתאמנים קשה כמעט לא מקבלים הזדמנויות להשתתף בתחרויות גדולות בארץ, והיא החליטה לשנות את זה."},{"t":"p","x":"היא יזמה להביא את השחיינים מספיבק לאילת, כדי שיתחרו גם הם ויחוו את האווירה של האירוע הגדול."},{"t":"p","x":"“זו הייתה אווירה מדהימה,” היא מספרת.“זה נתן להם שינוי, עוד אתגר ועוד תחרות.”"},{"t":"p","x":"לפעמים שינוי בעולם הספורט מתחיל מרעיון אחד קטן."},{"t":"img","src":"8f604f_78e1b343620240f0ba54b62c1fea00d2~mv2.jpeg","cap":"שרה מייסנברג באימון אופניים (צילום: שרה מייסנברג)"},{"t":"h3","x":"בין אימון, ארגון תחרויות ובניית הזדמנויות"},{"t":"p","x":"כיום שרה עובדת במרכז הספורט ספיבק ברמת גן, שם היא אחראית על קשרי חוץ ותמיכה בגיוס משאבים עבור פעילות הספורטאים. אבל היא לא נשארת רק מאחורי שולחן."},{"t":"p","x":"היא גם מאמנת כדורסל בכיסאות גלגלים לצעירים בתוכנית מיוחדת."},{"t":"p","x":"ואפילו התחילה ללמוד קורס מאמני אופניים."},{"t":"p","x":"“אני כבר רוכבת הרבה שנים,” היא מציינת, “ועכשיו החלטתי לעשות קורס מדריכים. בעוד חודש אני מסיימת ומקבלת תעודה.”"},{"t":"p","x":"יא מאמנת רכיבה פעמיים בשבוע לצעירים עם מוגבלויות וממשיכה להתחרות בעצמה."},{"t":"p","x":"מבחינתה ספורט הוא לא מקצוע."},{"t":"p","x":"הוא דרך חיים."},{"t":"h3","x":"למצוא את הספורט שהוא כיף"},{"t":"p","x":"כששואלים את שרה מה יכול לגרום לנערה להתחיל לעסוק בספורט היא לא מדברת על מדליות."},{"t":"p","x":"היא מדברת על חוויה."},{"t":"p","x":"“הדבר הכי חשוב הוא שזה יהיה כיף,” היא אומרת. “צריך לתת לילדות הזדמנות להתנסות בכמה סוגי ספורט עד שהן מוצאות מה מתאים להן.”"},{"t":"p","x":"כי ברגע שמוצאים את הענף הנכון משהו נפתח."},{"t":"p","x":"בביטחון."},{"t":"p","x":"בגוף."},{"t":"p","x":"בחיים."}]},"מרץ-המשוגע-מתחיל-בהשתתפות-הנציגות-הישראליות-במכללות-חגי-פלק-c":{"b":[{"t":"p","x":"אם יש משהו שיכול לתת קצת אסקפיזם חיובי בכל הכאוס שאנו נמצאים בו כעת מאז שבת בבוקר, זהו חודש 'מרץ המשוגע' כפי שהאמריקאים מכנים אותו ומדובר באליפויות המכללות שמתחילה השבוע בטורנירים האזוריים ועד לתחילת האליפות הארצית בסוף השבוע הבא."},{"t":"p","x":"כדי לעשות לכן סדר בעיקר בגלל ריבוי הנציגות הישראליות בNCAA שאת רובן אנו מסקרים, הבולטות שבהן גם הצליחו להביא את חברותיהן בדירוגים גבוהים נעשה לכן סדר:"},{"t":"p","x":"הראשונה והיחידה שהבטיחה את מקומה באליפות הארצית היא ירדן גרזון מרילנד שמשחקת במחוז BIG Ten  ומדורגת 13 בארה\"ב. מרילנד דורגה רביעית באזור המזרחי העפילה לסיבוב השני בטורניר האזורי כך שתארח בשישי הקרוב את המנצחת בין **פרדו של הילה קארש **או אורגון בשעה 04.00 לפנות בוקר."},{"t":"p","x":"כאמור באליפות הארצית היא מדורגת רביעית ותארח את המשחק הראשון באליפות הארצית שתיפתח ב-14/3."},{"t":"img","src":"542232_2977df66a14b454bb0fc7d4317bd29a1~mv2.png","cap":"ירדן גרזון  - רגע לפני הדראפט תנסה להביא את מרילנד הכי גבוה שאפשר"},{"t":"p","x":"**רומי לוי **שגם היא נמצאת בשנה האחרונה ומשחקת במדי וירג'יניה שערכה שלשום את הטקס המסורתי לכל חמשת הבוגרות שלה במשחק הבית האחרון של העונה הסדירה, תפתח את טורניר הACC בסיבוב השני במשחק ביתי מול קלמנזון (חמישי 18.00 בערב)."},{"t":"img","src":"542232_4c1e6b7db4d344a7b998dc5846b9cfad~mv2.png","cap":"רומי לוי במהלך טקס הפרידה מהבוגרות שנערך בתחילת השבוע במשחק מול וירג'יניה טק"},{"t":"p","x":"**גל רביב **שגם כן משחקת במחוז הACC במדי מיאמי הוריקן אליה עברה השנה סיימה גם היא את העונה הסדירה שבה מיאמי איכזבה מעט מבחינת הציפיות שאליה כיוונה ותנסה לשפר עמדות בטורניר המחוזי. מיאמי תפגוש כבר מחר בסיבוב הראשון במשחק ביתי את סטנפורד (18.00) בה נמצאת היהודיה **קרלי אמבורן **בת ה-19 שהוזכרה בעבר כמועמדת לחזק את נבחרת העתודה ועשויה לשחק בקיץ במכביה במדי נבחרת ארה\"ב."},{"t":"img","src":"542232_8c555949d63c4fb1acbb7d3f73c85e10~mv2.png","cap":"גל רביב - עונה מאתגרת במיאמי ופציעה מעצבנת.. מחכים לך בקיץ.."},{"t":"p","x":"**נועה גבעון **שמסיימת השנה גם היא את תקופתה במכללות ומשחקת באוניברסיטת רוברט מוריס, תפתח את טורניר מחוז BHL בחמישי לפנות בוקר במשחק חוץ נגד פרדו פורט-ויין במסגרת הסיבוב הראשון."},{"t":"img","src":"542232_9e0569301f644a06ba8af70e7c60a5c5~mv2.png","cap":"נועה גבעון - מסיימת את תקופתה במכללות עם שנתיים נהדרות ברוברט מוריס"},{"t":"p","x":"מכאן לשחקניות שעוד לא סיימו את העונה הסדירה:"},{"t":"p","x":"**תמר זינגר** שהובילה את מיאמי-אוהיו לפסגת מחוז הMAC כאשר היא שוברת שיאים אישיים בנקודות וכן את כמות האסיסטים לרכזת באוניברסיטה. לזינגר וקבוצתה נשארו עוד שני משחקים לסיום העונה הסדירה - בחמישי נגד קנת סטייט, ובראשון לפנות בוקר דרבי נגד אוהיו."},{"t":"img","src":"542232_d5813dabe58e4846bb7aa35c9038fe0a~mv2.png","cap":"תמר זינגר - עונה שוברת שיאים"},{"t":"p","x":"**שיראל נחום** שמשחקת במדי ארווין קליפורניה וזכתה באליפות מחוז BIG WEST לפני שנתיים בעונתה הראשונה, תנסה לשחזר את ההישג השנה כאשר הקבוצה שלה מוליכה את המחוז. גם לארווין נותרו שני משחקים - בשישי דרבי ישראלי מול קאל פולי בה משחקת** מאיה שרביט**, ובראשון נגד אוניברסיטת דייויס שנאבקת איתה על הפסגה."},{"t":"img","src":"542232_5ebc8985c52744098cf6092fbdb65e5a~mv2.png","cap":"שיראל נחום - ארווין תשחזר את העלייה לאליפות הארצית?"}]},"תוצאות-המחזור-ה-14-בליגת-אתנה-ווינר-לנשים-ר-ג-עדיין-מושלמת-רמלה-הביסה-את-אשדוד-ניצחונו":{"b":[{"t":"p","x":"ר\"ג עדיין מושלמת; רמלה הביסה את אשדוד. ניצחונות חוץ לחיפה וירושלים. פ\"ת הפתיעה את ראשון."},{"t":"p","x":"**המשחק המרכזי**"},{"t":"p","x":"**אליצור לנדקו רמלה - מכבי JE-Z אשדוד 62:84**"},{"t":"p","x":"במשפט אחד: נגמר מוקדם מדי.."},{"t":"p","x":"תקציר המשחק:"},{"t":"p","x":"רמלה שלה עדיין משחקים חסרים מול פ\"ת ואשדוד מתקרבת לצמרת ומתחילה להציג את היכולת המצופה ממנה. אשדוד הגיעה להתמודדות ללא אלבינה רזהיבה אך עם הרכש החדש קורטני ריינג' שסיפקה הופעה סולידית של 18 נק' ו-10 כ\"ח."},{"t":"p","x":"בניגוד למשחק מול כרמיאל הפעם רמלה הגיעה מוכנה ודרוכה מול יריבתה המושבעת ועלתה ליתרון דו ספרתי כבר בשלב מוקדם (34:46 בהפסקה)  ולמרות קאמבק של אשדוד ברבע השלישי, המארחת שוב העבירה הילוך בדרך לניצחון חד צדדי."},{"t":"p","x":"גזרת הישראליות: רמלה -עדן רוטברג הקפטנית שנמצאת בתקופה טובה מאד המשיכה אותה עם 16 נק' ו-7 כ\"ח; ליאור גרזון סבלה מערב התקפי חלש ואחוזים נמוכים הוסיפה 7, ומאי רווח ומיקה ביתן תרמו 6 נק' משותפות מהספסל;"},{"t":"p","x":"אשדוד: ערב חלש מאד לישראליות של הדאבליסטית. הדר חדד שפתחה בחמישייה סיימה עם 8 נק' ודור סער עם 6 בלבד. מהספסל רק טליה סירני תרמה 2 נק' כאשר מאיה זילברשלג לא קלעה."},{"t":"p","x":"המצטיינת: מיקיה האריגן שלטה ללא עוררין בצבע וסיימה עם 21 נק' ו-18 כ\"ח. (מדד 28)."},{"t":"p","x":"**הפועל ICL באר שבע/דימונה - מכבי הפניקס חיפה 73:64**"},{"t":"p","x":"במשפט אחד: הנור נדלק מחדש.."},{"t":"p","x":"תקציר המשחק:"},{"t":"p","x":"הירוקות סיימו עם 32 נקודות בצבע ו-22 נקודות מאיבודי כדור, זאת לעומת 20 בצבע של באר שבע ו-11 נקודות מאיבודי כדור של המארחת.  קריסטל ברדפורד שחזרה לארץ להופעת בכורה מחודשת אצל העולה החדשה  הוליכה את הקלעיות אצל הדרומיות עם 16 נק', 10 כ\"ח ו-5 חט'  בעדו לאשה טיאן פטרי הובילה מנגד עם 23 משלה."},{"t":"p","x":"גזרת הישראליות: חיפה - נור כיוף 16 נק', 8 כ\"ח ו-6 אס' במשחק נהדר;"},{"t":"p","x":"באר שבע: שדא כנען המשתפרת עם 13 נק', גלי קונטס 7, טלקר 5 ובייקו 2."},{"t":"p","x":"המצטיינת: נור כיוף - מדד 23."},{"t":"p","x":"**מכבי כרמיאל/בית הכרם - מכבי עירוני רמת גן 79:69**"},{"t":"p","x":"במשפט אחד: לא עוצרת בשביל אף אחת.."},{"t":"p","x":"תקציר המשחק:"},{"t":"p","x":"כרמיאל למרות סגל קצר מאד לאחר שצירפה גם את אנט סנואו,  הצליחה להוות יריבה עיקשת וקשה לפיצוח במחצית הראשונה וזאת בזכות יכולת נהדרת של ניצן עמר שצלפה 17 נק' (4 שלשות) במחצית הראשונה וזאת למרות ערב חלש מאד של אלישיה ג'נקינס שהייתה רחוקה מהיכולת שלה, והסתבכות בעבירות של אריאל הירן ואופיר לביא. ר\"ג נהנתה מאווירה ביתית בזכות קהל רב שהגיע מכפר קמא לכבודה של אליס חתוקאי.  שיר תירוש הייתה שם בשביל רמת גן בכל פעם שכרמיאל ניסתה לייצר מומנטום והצליחה יחד עם גילי אייזנר לרדת להפסקה בפיגור 37:35 בלבד."},{"t":"p","x":"במחצית השנייה ההגנה של רמת גן הייתה חדה ואגרסיבית ונהנתה גם מקרדיט מובהק של השופטים ולא אפשרה לכרמיאל זריקות קלות. ר\"ג הפכה את התוצאה עם פתיחת המחצית השנייה וכבר עלתה ליתרון דו ספרתי. כרמיאל בזכות יכולת טובה של אריאל הירן שסיימה עם 30 נק' הצליחה להיצמד מעט ובהחלט הסגל הקצר שלה גורם לה להגיע לבאר אך לא לשתות ממנה."},{"t":"p","x":"גזרת הישראליות: ר\"ג - שיר תירוש במשחק מצוין משני צידי המגרש (בעיקר בהגנה שם גם קיבלה קרדיט גדול מהשופטים) 22 נק' (14/6 מהשדה). גילי אייזנר במשחק סולידי עם 9 נק' ו-4 אס', ואליס חתוקאי הוסיפה 7 ובעיקר קהל רב שהגיע מכפר כמא לצפות בה. כרמיאל נהנתה ממחצית ראשונה מדהימה של ניצן עמר שקלעה בה 17 נק' אבל נעצרה על עוד 3 בלבד במחצית השנייה וסיימה עם 20 נק' (7/4 מחוץ לקשת). יול טויטו הוסיפה 4 נק' מהספסל. אופיר לביא שנקעה את קרסולה סמוך לסיום שוב לא הצליחה להיכנס למשחק."},{"t":"p","x":"המצטיינת: כרגיל ויקטוריה ויויאן שהשתלטה על המשחק במחצית השנייה והפכה את הפיגור הזעיר ליתרון של האורחות סיימה עם 22 נק' ו-7 כ\"ח (מדד 24)."},{"t":"img","src":"974295_26ce4fdf4fa7405488d6590d64bda84e~mv2.jpg","cap":"״קהל רב הגיע לראות את שחקנית רמת גן- אליס חתוקאי״, צילום: יעל אמסילי, מנהלת ליגת העל"},{"t":"p","x":"**בנות 'בני פתח תקווה - הפועל ראשון לציון 54:62**"},{"t":"p","x":"במשפט אחד: כחול ולבן זה הצבע שלהן - הישראליות של פ\"ת הובילו לניצחון מרשים"},{"t":"p","x":"תקציר המשחק:"},{"t":"p","x":"ניצחון גדול לקבוצה מאם המושבות שמתקרבת לבית העליון והובילה כבר ביתרון דו ספרתי. ראשון לציון סיימה עם 13% בלבד מחוץ לקשת כאשר  פתח תקווה הצליחה לעצור את האורחות ברבע הראשון והשלישי על 10 נקודות בלבד בכל אחד וזה היה הגורם המשמעותי לניצחון המרשים."},{"t":"p","x":"גזרת הישראליות: פ\"ת - אופיר קסטן רז סיימה סוף סוף עם דאבל פיגר של 11 נק'. מאי דיין הוסיפה 8, ונועה וושדי וג'ניפר פליישר גם כן 8 בצוותא;"},{"t":"p","x":"ראשון לציון סבלה מערב חלש מאד של הישראליות שלה- יערה יצחקי סיימה עם 9 נק' אך עם שלשה אחת בלבד, ועדן ציפל תרצה לשכוח את השבוע הזה אחרי שסיימה את הערב ללא נק' וללא זריקה לסל (6 אס')."},{"t":"p","x":"**אליצור חולון - הפועל לב ירושלים 78:77**"},{"t":"p","x":"במשפט אחד: תוצאה נוסטלגית ודרמתית עם תובנות להמשך"},{"t":"p","x":"תקציר המשחק:"},{"t":"p","x":"לב ירושלים יוצאת עם ניצחון חוץ גדול מחולון ומתקרבת לצמרת הגבוהה. האורחות מירושלים סיפקו רבע שלישי מצוין שהסתיים בתוצאה 7:21, כאשר הסיום היה של המצטיינת בירושלים, סאוונה ווילקינסון שהכריעה את ההתמודדות מקו העונשין 3 שנ' לסיום."},{"t":"p","x":"גזרת הישראליות: ירושלים - נטע מישר פתחה בחמישייה (35 דק') אך סיימה עם 4 נק' בלבד. ג'וי אוסיגאווי והדר מור יוסף הוסיפו 3 כ\"א."},{"t":"p","x":"בחולון אליסה ברון-פלג חזרה למספרים ובעיקר ליכולת שהתרגלנו לראות עם 16 נק' באחוזים טובים ו-6 אס'; מעיין כהן הוסיפה 10 נק' אך באחוזים נמוכים מחוץ לקשת, ואיילה אורן סיימה עם 3 נק' כאשר צליל וטורי מסיימת ללא נק'."},{"t":"p","x":"המצטיינת: סוואנה ווילקינסון שהכריעה את המשחק בלטה עם 25 נק' ו-10 כ\"ח (מדד 28) דווקא מול קבוצתה בעונה שעברה."}]},"זו-שבאה-וזו-שהולכת-מדוע-אי-אפשר-אחרת-על-רכבת-חילופי-הזרות-בליגת-העל-לנשים-בכדורסל":{"b":[{"t":"p","x":"ליגת העל לנשים מתקרבת לסיום מחצית העונה (סיום הסיבוב השני) ואפילו אליצור רמלה שהיא היחידה שעשתה שינויים על הקווים מתקרבת להשלמת משחקי הליגה שנותרו לה שאחריהם הטבלה אמורה להתיישר. כל זה לא משנה את העובדה שהעונה הזו - ככל הנראה נשברו שיאי החילופים בסגלי הקבוצות, וכמובן שאין כל טענה לשחקניות הישראליות - הוותיקות והצעירות שעדיין נשארו כאן לפני שחלקן מצטרפות לחברותיהן  מעבר לים, אלא לתחלופה הבלתי נגמרת של חילופי הזרות מאז הליגה עברה לשחק עם 4 זרות - 2 שחקניות עם דרכון אמריקאי ושתי שחקניות עם דרכון אירופאי."},{"t":"p","x":"כל הקבוצות בלי יוצא מן הכלל עשו חילוף אחד או שניים במצבת שחקניות החיזוק שלהן. חלקן כמו לדוגמא העולה החדשה מכרמיאל וגם בנות פתח תקווה לאחרונה,  נאלצו לעשות זאת בגלל פציעות. חולון שבנתה קבוצה חזקה מבחינת השלד הישראלי שלה, עשתה חילופים מוקדמים כדי לאזן את הסגל ויכול להיות שמצאה את הנוסחה הנכונה לחיבור מחודש. מנגד בולטת העובדה שהרבה מהקבוצות החליטו לעשות זאת עקב שיקולים מקצועיים. בהסתכלות על הטבלה למעט באר שבע שנמצאת זמן ממושך במקום האחרון, יתר הקבוצות נאבקות על כניסה לבית העליון או הסתבכות ממאבק נגד הירידה."},{"t":"p","x":"נזכיר כי העונה הליגה השתנתה והשיטה שלה דומה לליגת העל לגברים כאשר בתום הסיבוב השני ייערך סיבוב שלישי בין שש הראשונות מול 4 התחתונות, כאשר המקום השביעי והשמיני יעפילו לסדרות רבע גמר הגמר-סל בהתאמה."},{"t":"p","x":"המכנה המשותף למרבית הקבוצות אשר החליטו להחליף זרות טמון בשלושה דברים עיקריים: **עבודה עם סוכנים קבועים המייצגים  מגוון של שחקניות העמדה שאותה קבוצה רוצה,** קושי בלהביא שחקניות בעלות דרכון אירופאי לעומת אלו שעם דרכון אמריקאי, בעיקר כאלו עם עבר בארץ - לאורך העונות האחרונות רוב הקבוצות שהולכות על הישן והמוכר ומביאות שחקניות בעלות ניסיון בארץ כמו חולון שהחזירה את שיי קלי, או אפילו באר שבע שהחזירה את קריסטל ברדפורד למרות עברה המורכב."},{"t":"p","x":"סבלנות בחיבור סגל שעובר שינויים תוך כדי העונה (והדבר נכון בכל קבוצה בכל ליגה - על אחת כמה וכמה שמדובר בליגה מקצוענית). גם בליגת העל לגברים וגם בליגה הלאומית לגברים הקבוצות מתקשות לעשות שינויים בסגל ובעיקר להביא שחקני חיזוק חדשים כי השוק חלש. אפשר לתת דוגמא טובה דווקא להפועל לב ירושלים שהיתה סבלנית, עשתה את השינויים שהצוות המקצועי שלה דרש, אבל לא ויתרה על הזהות הישראלית ונתנה הזדמנויות לשחקניות הצעירות שלה. כך גם בפתח תקווה, בראשון לציון שתמיד נותן הזדמנות לשחקניות הבית שלו, ובחיפה נעמה הלוי שחזרה מפציעה ומתחילה להזכיר את היכולת שהציגה בלאומית על חשבונה של טיה פרסלי שהקריירה שלה עומדת לפני סיום."},{"t":"p","x":"מנגד מעניין יהיה לראות באליצור רמלה שם הלחץ להישגים תמיד קיים כמו גם באשדוד שהחליטה להיפרד מסטשה קארי ולהחליפה בקורטני ריינס שכבר עברה בארץ האם הרוטציה תורחב. ברמלה עשויה ג'ני סימס לחזור בקרוב ותוסיף עוד עומק לסגל כ'ישראלית' אך האם זה יגרום לכך שדקות המשחק של הצעירות הישראליות יופחתו עוד יותר? נצטרך להמתין ולראות."},{"t":"img","src":"974295_10c624f0a83e40d8a016a4b539b517df~mv2.jpeg","cap":"״דקות המשחק של הצעירות יופחתו עוד יותר?״ צילום: יעל אמסילי, מנהלת ליגת העל"}]},"סיכום-מחזור-13-ליגת-העל-לנשים-c":{"b":[{"t":"p","x":"**רמלה הזיעה מול כרמיאל שהצליחה לחזור מפיגור אך לא לנצח; ר\"ג ממשיכה לטייל; אשדוד ניצחה בעיר היין בשחזור סדרת הגמר ועלתה למקום השני; חולון נקמה בחיפה, פ\"ת עם ניצחון חוץ מרשים בעיר הבירה. **"},{"t":"p","x":"**המשחק המרכזי**"},{"t":"p","x":"**אליצור לנדקו רמלה - מכבי כרמיאל/בית הכרם 79:83  **"},{"t":"p","x":"**במשפט אחד: **'יותר טוב כלום מכמעט'"},{"t":"p","x":"תקציר המשחק:"},{"t":"p","x":"אפשר לחלק את הדרמה שהתחוללה אמש ברמלה לשני חלקים. רמלה בהחלט נראית קבוצה אחרת בעידן טל נתן השיפור ביכולת הקבוצתית שלה נובע מכך בעלייה ביכולת של הישראליות המובילות שלה וברגע שהיא רוצה לשמור היא גם עושה את זה. יחד עם זאת כדי להגיע למקומות שהיא רוצה להגיע היא תצטרך לסתום את החורים הגורמים לעליות וירידות במשחק שלה כמו שקרה לה ברבע האחרון. כרמיאל שהגיעה עדיין עם סגל קצר מאוד, סבלה גם מכך הקפטנית אופיר לביא נאלצה לשחק עם שפעת עד שלא יכלה יותר וזה הספיק להיות צמודה עד להפסקה - 43:37."},{"t":"p","x":"במחצית השנייה רמלה עלתה כבר ליתרון דו ספרתי ועלתה ליתרון 14 (54:68). אבל לדניאלה ראובן יש ארגז קסמים והיא השתמשה בו כאשר אריאל הירן בעוד מופע הרואי רגע לפני שהיא נפרדת ואלישיה ג'נקינס סחפו את כרמיאל ברבע אחרון מדהים עד למינוס 2 (79:77) שתי דקות לסיום. לרוע מזלן הן לא הצליחו לנצל איבוד כדור של ליאור גרזון והחטאה של ג'נקינס מחצי מרחק וריב' התקפה של צ'לסי נלסון 16 שנ' לסיום חרץ את גורל המשחק."},{"t":"p","x":"רמלה: **רוטברג** 19 נק', נלסון 16 ו-10 כ\"ח,  גבירנטס  14,  האריגן 10 (7 כ\"ח), **גרזון,** רווח (7 אס') ובוסגנה 8 כ\"א."},{"t":"p","x":"לכרמיאל: הירן **35 נקודות**, גומז 20, ג'נקינס 14 (**13** כ\"ח),  עמאר 8, טויטו 2."},{"t":"img","src":"bf0bf7_7f75de955d9f4dd39481baedaab7e4c4~mv2.jpg","cap":"אליצור רמלה קרדיט: דני מרון , באדיבות המנהלת"},{"t":"p","x":"**מכבי בנות ר\"ג - הפועל icl באר שבע/דימונה 60:96**"},{"t":"p","x":"**במשפט אחד: **טיול לעת ערב"},{"t":"p","x":"מוליכת הטבלה לא נזקקה למאמץ מיוחד בהתמודדות מול נועלת הטבלה שמתקרבת מרגע לדודלי חזרה לעבר הליגה השנייה וסגרה עוד ניצחון חד צדדי לפני משחק גמר גביע הליגה בחמישי הקרוב."},{"t":"p","x":"גורסיץ'  במשחקה הטוב ביותר העונה הובילה עם 21 נק' ו-7 ריב', **אליס חתוקאי **הוסיפה 19, ויויאן 18 (8 כ\"ח) ואימרי תומס 11. אייזנר ותירוש תרמו בצוותא 16 נק' ו-11 אס'. בבאר שבע ניתן לציין לטובה את שדה כנעאן עם שיא הקריירה בליגת העל של 19 נק' (7/4 מה-3)."},{"t":"p","x":"**הפועל ראשון לציון - מכבי JE-Z אשדוד 75:69 **"},{"t":"p","x":"**במשפט אחד:** מסתכלות אל העבר אך מתרכזות בהווה"},{"t":"p","x":"תקציר המשחק:"},{"t":"p","x":"סגנית האלופה הדאבליסטית מעיר הנמל נפגשו למשחק מאתגר ומעניין בהיכל גן נחום."},{"t":"p","x":"המארחת שלטה במשחק במשך שלושה רבעים אך שמטה יתרון 9 ולרבע האחרון עלו הקבוצות ביתרון 49:51 בלבד לראשון לציון. ברבע האחרון אשדוד השתלטה על המשחק ושלשה של סטפני ווטס הפכה את התוצאה כאשר האורחות כבר רצות ליתרון 8 (57:65). בולדרב הצליחה לצמק בשלשה עד למרחק מהפך (64:63, 35) אבל קסניה מלשקה וסטשה קארי במשחקה הטוב ביותר פתחו בריצה חדשה ושמרו על היתרון עד לסיום."},{"t":"p","x":"סטשה קארי הובילה את קלעיות אשדוד עם 16 נק' ו-10 כ\"ח; מלשקה הוסיפה 12 ו**דור סער** במשחק סולידי 11 נק'. הדר חדד ומאיה זילברשלג תרמו ביחד 16 נק'."},{"t":"p","x":"מנגד יינג סיימה עם 18, בולדרב  15 ובוגיצ'יץ'  13, אך ראשל\"צ נעצרה לאחר שני ניצחונות, למרות 11 נקודות כ\"א של **עדן ציפל** ויערה יצחקי (7 אס). אשדוד שלה עדיין משחק חסר מול רמלה התקרבה למקום השני בטבלה."},{"t":"p","x":"**מכבי הפניקס חיפה - אליצור חולון 78:77 **"},{"t":"p","x":"**במשפט אחד**: נקמה קרה 1  בטעם נוסטלגי"},{"t":"p","x":"תקציר המשחק:"},{"t":"p","x":"חולון הגיעה בפעם השנייה בתוך פחות משבוע לעיר הכרמל במטרה לנקום ספורטיבית בהפסד הצורב והודחה מגביע המדינה אך גם הפעם נקלעה למשחק קשה. רק ברבע השלישי הצליחו אליסה ברון ושי קלי לייצר בריחה קלה ועלו ליתרון 9. חיפה הצליחה לגלות אופי ושיין סלרס מחקה את היתרון עד למינוס 3. חולון עוד הובילה אבל אז הגיעה נעמה הלוי שעם 5 נק' רצופות קבעה שוויון 77, 9 שנ' לסיום. חולון חזרה מפסק זמן, ברון לקחה זריקה טובה אך החטיאה אך למזלה שיי קלי השתלטה על הכדור החוזר 3 שנ' לסיום, הלכה לקו ודייקה פעם אחת. הזריקה האחרונה של נור כיוף הלכה החוצה והירוקות צברו הפסד שביעי ברציפות."},{"t":"p","x":"ליה בראון שממשיכה להשתלב היטב  הובילה את חולון לצד  שיי קלי עם 19 נק' כ\"א,  **ברון **סיימה עם 17 אך שוב ללא שלשה,  ו **צליל וטורי** עם 11 ו-7 ריב'. מעיין כהן תרמה 8 נק' מהספסל.  בצד השני סלרס בלטה כרגיל עם לא פחות מ-29 נק' ו-10 אס', מונונגה קלעה 13 ו-8 ריב', וכיוף חזרה למספרים של פתיחת העונה עם 12 נק', 6 כ\"ח ו-6 אס'. הלוי כאמור תרמה את הנקודות החשובות אך חיפה לא מקבלת כלום מטיה פרסלי שנראית כפי שהקריירה שלה על סף סיום."},{"t":"p","x":"**הפועל פארק בית הכרם/לב ירושלים - בנות 'בני' פתח תקווה 83:64**"},{"t":"p","x":"**במשפט אחד: **נקמה קרה חד צדדית"},{"t":"p","x":"תקציר המשחק:"},{"t":"p","x":"כמו בעונה שעברה, גם הפעם החליטו בלב ירושלים להתרכז בגביע בשבוע הכפול והגיעו להתמודדות השנייה בתוך פרק זמן קצר מול הקבוצה מאם המושבות ללא דסטני ליטלסון, מיכאלה לזיץ', ירדן דנן ונועה מגד שככל הנראה גמרה את העונה. פתח תקווה מצידה הגיעה ללא נג'אי פולארד שנפצעה בחמישי האחרון וגם היא סיימה את העונה."},{"t":"p","x":"למרות זאת הקבוצה מאם המושבות פתחה מצוין וסגרה עניין כבר ברבע הראשון עם 7:33 כאשר המשחק שלה היה שוטף משני צידי המגרש ובהפסקה 20:54 כאשר היא צולפת לא פחות מ**-11 שלשות מחוץ לקשת. **המחצית השנייה הייתה לפרוטוקול כאשר שתי הקבוצות משתפות דקות ארוכות את צעירות הסגל."},{"t":"p","x":"ספארקל טיילור הובילה את פ\"ת עם 26 נק', מאי דיין תרמה 14 (4 שלשות)  ו בויאנה קובסביץ' התקרבה לטריפל דאבל עם  12 נק' 13 כ\"ח ו-8 אס'."},{"t":"p","x":"אצל ירושלים הייתה זו  הדר מור יוסף שהובילה עם 19 נק' (5 שלשות) ' ווילקינסון בלטה עם 13 ו-10 כ\"ח וג'וי אוסיגאווי קלעה 10 מול האקסית."},{"t":"img","src":"bf0bf7_315d52fc60ea4062aa2c6206d163081d~mv2.jpg","cap":"דניאלה ראובן קרדיט: דני מרון , באדיבות המנהלת"}]},"לא-פורשת-נועה-זליבנסקי-שוברת-טאבו-בכדורסל-הישראלי":{"b":[{"t":"p","x":"שחקנית הכדורסל הבכירה ומקימת המיזם- יוצאת להיריון ודורשת לנרמל אימהות בספורט הנשים מבלי לפרוש: \"זה לא רק סיפור אישי. זו משימה לאומית“"},{"t":"p","x":"כשהיא בשיא הקריירה ועם אהבה שלא נגמרת למגרש, נועה זליבנסקי יחזקאל עושה מה שכמעט ולא רואים בכדורסל הישראלי: לוקחת פסק זמן להיריון מבלי לפרוש. בראיון פתוח וכנה היא מדברת על הגוף שמשתנה, האימונים המותאמים, על היעדר המעטפת, על הפחדים – ובעיקר על מה שהמדינה והמערכת מסרבות לראות: לידה היא לא סוף קריירה. היא חלק ממנה."},{"t":"img","src":"8f604f_72a5b5337d814f9da74ca7d4e72d29cc~mv2.jpeg","cap":""},{"t":"p","x":"בישראל, רוב שחקניות כדורסל מביאות את הילד הראשון רק אחרי פרישה מהענף. עבור רובן אמהות נתפסת כקו סיום בלתי רשמי לקריירה. בגיל 29, כשקריירת הכדורסל שלה עדיין רחוקה ממיצוי, נועה זליבנסקי יחזקאל בחרה אחרת: להיכנס להיריון מבלי לוותר על הזהות הספורטיבית שלה."},{"t":"p","x":"לא מתוך קלות דעת אלא מתוך תכנון מוקדם והבנה עמוקה של המחיר האישי והמקצועי. “ידעתי שאני רוצה להיות אימא צעירה. זה תמיד היה אחד החלומות שלי”, היא מספרת. “ידעתי שאצטרך לעצור רגע את הקריירה, אבל לא לוותר עליה”."},{"t":"p","x":"זליבנסקי מודה שלא היו לה כמעט מודלים לחיקוי. “אני אחת הבוגרות בליגה הישראלית, ועדיין לא גדלתי עם דוגמאות של שחקניות שיצאו ללידה וחזרו לשחק.”** יוצאת הדופן הייתה גלית דבש, שחקנית נבחרת ישראל בכדורעף ואם לשניים, שהפכה עבור זליבנסקי למודל השראה. “גלית הראתה לי שאפשר לעצור רגע, להביא ילדים ולחזור לספורט בלי לוותר על מי שאת”**, היא אומרת, “הבנתי שהפעם אני קופצת למים לא רק בשבילי אלא גם בשביל אחרות”."},{"t":"p","x":"באופן מפתיע, האתגר הגדול ביותר לא היה פיזי אלא מנטלי. ספורטאית תחרותית רגילה כל חייה לדחוף קדימה: להתחזק, להשתפר, להעמיס. ההיריון דורש בדיוק את ההפך."},{"t":"p","x":"“פתאום את לא מנסה להיות יותר חזקה מיום ליום”, היא מסבירה, “אלא ללמוד לקחת אוויר. לעצור. להקשיב לגוף. זה סותר לגמרי את האינסטינקט של ספורטאית”."},{"t":"p","x":"עם גילוי ההיריון נאלצה זליבנסקי להיפרד מהמגרש ומהמשחק האגרסיבי שמאפיין אותה. “ידעתי שאין לי דרך להמשיך לשחק. המשחק שלי פיזי, עם הרבה מגע. עברתי לאימוני חדר כושר מותאמים. אני מתאמנת ארבע פעמים בשבוע, אבל זה רחוק ממה שהגוף שלי רגיל”."},{"t":"p","x":"**ההבנה שלא כל מה שהיה נכון קודם נכון גם עכשיו הייתה אחד התהליכים המאתגרים ביותר.**"},{"t":"p","x":"ההיריון לא רק מרחיק מהמגרש. הוא חושף פער עמוק במערכת הישראלית. “אין מעטפת מסודרת לספורטאיות בהיריון”, אומרת זליבנסקי. “אין מספיק מאמני כושר מהספורט התחרותי שיודעים איך לעבוד עם ספורטאית בהיריון ואחרי לידה. אין פרוטוקולים, אין הכשרות, אין כמעט מחקר”."},{"t":"p","x":"דווקא מחוץ לספורט ההישגי היא גילתה ידע רב יותר.** “בעולם העממי יש מאמנים שמבינים בזה. אבל בספורט התחרותי נותנים תחושה שאסור להיכנס להיריון. כאילו אמהות וספורט לא יכולים לדור בכפיפה אחת”.**"},{"t":"p","x":"לדבריה, בעולם כבר הבינו אחרת. “תסתכלו על ה־WNBA. שחקניות חוזרות אחרי לידה ומשחקות גם בגיל 35–37. שם זה מנורמל. כאן זה עדיין טאבו”."},{"t":"p","x":"אחד הפרטים הפחות מדוברים, אך המשמעותיים בהחלטה של זליבנסקי, הוא הבחירה לעבור את התקופה הזו מבלי להיות חתומה בקבוצה. “היה לי חשוב לא להיות תלויה באף אחד”, היא מסבירה. “אני לא יודעת כמה תמיכה יש היום לספורטאיות שחתומות בקבוצות ונכנסות להיריון. זו שאלה שהמערכת עוד לא באמת מתמודדת איתה”."},{"t":"p","x":"**גם ההתרחקות מהקבוצה היא חלק מהמחיר. “כדורסל זה לא רק מקצוע – זו זהות. מגיל שש אני על מגרש. פתאום את לא חלק מהשגרה, מהחדר הלבשה, מהקבוצה.** זו בדידות שלא מדברים עליה מספיק. התמזל מזלי יש לי בן זוג מאוד תומך”."},{"t":"p","x":"עבור זליבנסקי, זה לא סיפור אישי או ענפי אלא כשל מערכתי. “זה תפקיד של המדינה”, היא מדגישה.** “לידה וחזרה לספורט זה חלק בלתי נפרד מספורט נשים. כשלא מנרמלים את זה – אנחנו מאבדות ספורטאיות מנוסות”.**"},{"t":"p","x":"היא מציינת נקודת אור אחת: ההכרה של ביטוח לאומי בהיריון של שחקניות כדורסל כהיריון בסיכון, המאפשרת שמירת היריון. “זו בשורה חשובה, אבל היא רחוקה מלהיות מספיקה. צריך מדיניות ברורה, מודעות, הכשרות ומעטפת אמיתית”."},{"t":"p","x":"כל עוד המערכת מתמקדת רק בגיוס ילדות ונערות לענף ומתעלמת ממה שקורה לספורטאיות שכבר נמצאות בו – ספורט הנשים ימשיך לדשדש. “אם ספורטאיות צריכות לפרוש כדי להביא ילדים זה הפסד של כולנו”."},{"t":"p","x":"נמשיך לפעול במיזם לקדם את הנושא הזה."},{"t":"p","x":"האם יש פחד? כן. האם הוא מנהל את ההחלטות? לא."},{"t":"p","x":"“אם זה היה מפחיד אותי באמת – לא הייתי עושה את זה”, אומרת זליבנסקי. “זה חדש, זה לא משהו שרואים הרבה, אבל אני יותר מתרגשת מאשר מפחדת”."},{"t":"p","x":"היא יודעת שהחזרה למגרש תהיה תהליך שדורש סבלנות – תכונה שהיא מודה שאינה החזקה שלה. “אני רגילה לעשות הכל כאן ועכשיו. פה אני יודעת שזה ייקח זמן, ואני כבר מתכוננת לזה מנטלית”."},{"t":"p","x":"**המטרה של נועה ברורה: לחזור לשחק בעונה הבאה בליגת העל. בלי לחץ זמנים נוקשה אבל עם רצון חד וברור. “אין יום שאני לא חושבת על החזרה. כדורסל זה מי שאני”.**"},{"t":"p","x":"מעבר לקריירה האישית, זליבנסקי מקווה להפוך למודל לספורטאיות נוספות. לא גיבורה אלא נורמה. “מעט מאוד מדברים על זה, אבל בעולם רואים לא מעט ספורטאיות שחוזרות אחרי לידה אפילו חזקות יותר”."},{"t":"p","x":"רגע לפני השנה האזרחית החדשה, הסיפור שלה הוא לא רק עדות אישית אלא קריאה לשינוי.שינוי ומודעות שמבקשים ממערכת הספורט, מהמדינה ומהאגודות להפסיק לפעול בהתאם לסטיגמות ישנות ולהתחיל לשאול איך מאפשרים לספורטאיות מנוסות להמשיך לייצג, להתחרות ולהוביל."},{"t":"p","x":"מבחינת נועה זליבנסקי, המסר ברור: “זה לא סיפור אישי. זו משימה לאומית”."},{"t":"img","src":"974295_f4e8e9181bea48ac9969e900a563ac9e~mv2.jpg","cap":"״לידה וחזרה לספורט זה חלק בלתי נפרד מספורט נשים.״  נועה זליבנסקי יחזקאל, צילום: עודד קרני"}]},"המנצחות-האמיתיות-על-המגרש-ובכל-זירה":{"b":[{"t":"p","x":"**כנס המצטיינות של WSP **"},{"t":"p","x":"**שינוי מציאות.**"},{"t":"p","x":"לנשים מצטיינות יש פה. יש קול. אבל כמה אנחנו באמת זוכים לשמוע אותו?המציאות בשטח עדיין לוקה בחסר, החשיפה בפריים טיים אפסית, התקצוב נמוך, והתודעה הציבורית כאילו תקועה אי שם בשנות ה־90. אם נלמד מהנעשה בעולם המערבי, נבין שאנחנו לא שם יותר!הנערות של היום רוצות לראות מודלים אמיתיים. נשים שמתאמצות, נופלות, קמות, מתמודדות, מנצחות – לא בגלל שהן מושלמות, בגלל שהן ממשיכות לשחק. נשים שלא מפחדות להציב יעדים ולכבוש אותם, לא משנה כמה הדרך מורכבת. ספורט הוא כבר מזמן לא רק תחרות. הוא שפה. מרחב. דרך חינוך. דרך חיים. והכנס הזה – הוא הזירה החדשה שנותנת עוד דחיפה קדימה."},{"t":"p","x":"**אנרגיה נשית במרחבים ישנים.**"},{"t":"p","x":"**WSP – Women's Sport Power** הוא לא קמפיין להעלאת מודעות. הוא מיזם חי שצמח מתוך השטח. מיזם ששם את הנשים במרכז – לא כגימיק, אלא ככוח מניע. זה לא רק עיסוק בשוויון בספורט. זו בניית תשתית. תשתית ששמה נשים ,וצמתיות כמודל, שנותנת את הבמה לנערות שהגיעו בלי ביטחון ויצאו עם גב זקוף. לנשים שמצאו בקבוצה בית, למאמנות .שלא מוותרות"},{"t":"p","x":"מיזם WSP מחבר בין ספורט, יזמות, חינוך והובלה נשית, מתוך אמונה כי ספורט הוא לא מטרה – הוא כלי. כלי שעוזר לגבור על פחדים, לחבר בין קהילות, להכניס אנרגיה נשית למרחבים שפעם היו טאבו גברי."},{"t":"p","x":"**רצות מאחורי הקלעים.**"},{"t":"p","x":"הנשים שמובילות את WSP הן לא דמויות פרסומיות – הן לוחמות יומיומיות: ספורטאיות ומאמנות בשטח, מייסדות קבוצות, בונות קהילה. כל אחת מהן עברה דרך, ונמצאת בתנועה מתמדת – מובילה איתה עוד נשים.הן לא מעוניינות רק לפרוץ את החסמים, הן באות **לבנות מציאות ספורטיבית חדשה** שתעודד ותזמין עוד ועוד ילדות, נערות ונשים לקחת בה חלק פעיל."},{"t":"p","x":"**זירת השראה נשית אמיתית**"},{"t":"p","x":"כנס _הספורטאיות המצטיינות _של WSP שיתקיים ביום רביעי, 26.6.25, בשעה: 18:00, במטה ,WSC SPORTSהוא זירת השראה – אבל גם זירת פעולה. הוא נקודת שיא בתנועה שלמה שמובילה שינוי בשטח, ויוצרת שפה חדשה של נשיות, הובלה וספורט. הכנס הוא חגיגה. חגיגה של הצלחה, של ספורטאיות ונשות ספורט מענפים שונים, שהצליחו, שפרצו את הדרך והקשיבו ללב. בכנס יוענקו פרסי \"המצטיינות\" של WSP לשנת 2025 והוא מחבר בין עולם הספורט והמרחב האישי של כל אישה שמבקשת לפרוץ. בין המשתתפות תוכלו לראות נשים משפיעות ממגזרים שונים בחברה: ספורטאיות, מנהלות, אקטיביסטיות, אמהות, חונכות, נשות חינוך.WSP מבקשות להיות קרקע בה נוצרים החיבורים שישנו את פני הספורט הנשי בישראל, להיות המקום שבו רעיונות הופכים ליוזמות, וחיבורים אישיים הופכים להובלה מערכתית שתשים זרקור על מה שבאמת חשוב לכולנו. זו לא במה, זה עיצוב מחדש הספורט הישראלי ואיתו של פני החברה הישראלית כולה."},{"t":"img","src":"ffb43f_16c71bc15cdc4e5298cf41c4014a5908~mv2.jpg","cap":""}]},"מגבלה-היא-לא-קיר-היא-שער":{"b":[{"t":"p","x":"**ורד אבנעים מאמנת לראות אחרת**"},{"t":"img","src":"ffb43f_10eb2dfa72c742e78c50a0f559112444~mv2.jpeg","cap":"צילום: יואב דודקביץ"},{"t":"p","x":"העולם יכול להיראות לפתע כמו שדה מוקשים של אתגרים וחוסר ביטחון, במיוחד כשהילד או הילדה שלך שונים מאחרים או מקבלים אבחנה רפואית. אבל אני רוצה לספר לך על מפה אחרת לגמרי – מפה שגיליתי בעקבות נשים כמו ורד אבנעים, שמובילות את הדרך להוכיח שהשוני או המגבלות הם רק נקודת ההתחלה."},{"t":"h2","x":"ילדה שקטה, מגרש רועש"},{"t":"p","x":"\"כילדה, ללימודים פחות התחברתי, אבל על המגרש מצאתי את עצמי.\" הספורט שינה עבור ורד את כל התמונה. היום, כרכזת ספורט פראלימפי מחוז דרום ועוזרת מאמן נבחרת ישראל נשים לשעבר בענף הכדור שער, ורד מובילה עשרות בני נוער עם צרכים מיוחדים, נכות פיזית או לקות ראייתית להאמין בעצמם - והיא רוצה שכל ילד וילדה יגלו את הכוח הייחודי שלהם."},{"t":"p","x":"ורד לא התחילה עם חלומות גדולים. בגיל 9 היא נרשמה לחוג טניס, מתעקשת להצטרף למרות שכל המשתתפים היו בנים. \"אמרתי לאמא שלי, 'פה אני אסתדר,'\" היא נזכרת בחיוך. משם היא עברה לכדורעף והפכה למאמנת בגיל צעיר."},{"t":"p","x":"ואז, כמעט במקרה, נתקלה בספורט הפראלימפי שהפך עבורה להרבה יותר ממשחק. \"נסעתי לתל אביב לראות משחק כדורשער של נבחרת ישראל נשים והתאהבתי,\" היא מספרת. \"היה שם משהו כל כך חזק – אנשים צעירים שמשחקים עם כל הלב, בלי תירוצים, בלי גבולות.\""},{"t":"h2","x":"טוקיו, פריז, באר שבע"},{"t":"p","x":"היא לא הסתפקה בצפייה. ורד חזרה לבאר שבע, הקימה קבוצות כדורשער משלה, והתחילה לבנות קהילה. \"בהתחלה היו שלושה-ארבעה שחקנים בקבוצה אחת,\" היא נזכרת, \"היום יש לנו קבוצות בכל הגילאים לכל סוגי המגבלות\"."},{"t":"p","x":"נקודת ציון חשובה, ורד שימשה כעוזרת מאמן נבחרת ישראל בטוקיו 2020 ובמשחקים בפריז, הנבחרת חזרה עם מדלית כסף כשורד משדרת את המשחקים בהתרגשות גדולה בערוץ הספורט. ענף הכדורשער הינו ענף שבו משתתפים עם לקויות ראייה משחקים עם כדור מצלצל כשכולם עם כיסוי עיניים כדי להשוות תנאים."},{"t":"p","x":"הספורט הפראלימפי מבחינתה הוא סמל של עוצמה שהיא רוצה להעביר לכל אדם באשר הוא. \"הכדורשער הוא לא רק משחק,\" היא אומרת. \"זה שיעור לחיים – לומדים להקשיב, לסמוך על עצמך, לסמוך על הקבוצה ולהילחם על כל נקודה ביחד. ראיתי שם אנשים ששינו את כל מה שחשבתי על החיים עם אתגרים שונים.\""},{"t":"h2","x":"אנשים שקורעים את המגבלה"},{"t":"p","x":"\"יש לנו שחיינית פראלימפית מדהימה בשם אחינועם, בת 25 שרופאים אמרו לה שהיא הגיעה לקצה היכולת שלה מבחינת השיקום ולא תוכל עוד להתקדם,\" היא משתפת. \"אבל לשמחתי זה לא עצר בעדה והיום היא שוחה, רוכבת על אופניים, ואפילו עוזרת לאמן שחיינים צעירים עם צרכים מיוחדים. זה לא רק ספורט – זה להוכיח לעולם שכל אדם יכול.\" ספורטאית נוספת בשם אורלי, קטועת רגל, מוצאת בענף אופני היד כוח להתמודד עם תקופות לא פשוטות. דרך הספורט היא מתחזקת, מאמינה בעצמה ומוכיחה לעצמה ולסביבה שאין דבר בלתי אפשרי."},{"t":"p","x":"דוגמא נוספת לספורטאית פורצת גבולות הינה ליהיא בן דויד, מדליסטית פראלימפית בנבחרת ישראל בענף הכדורשער, שמלבד היותה מהשחקניות המובילות בעולם, מעבירה את הניסיון והידע שלה הלאה כמאמנת בקבוצת באר שבע ומגדלת דור חדש וצעיר של ספורטאים ללא הבדל מין או מגבלה."},{"t":"h2","x":"יותר מסתם משחק"},{"t":"p","x":"אישית, אני יודעת בדיוק על מה ורד מדברת. לפני מספר שנים פנה אלי פרופסור שייקה הוצלר ממכון וינגייט בבקשה להשתתף במחקר על השפעות הספורט הפראלימפי על חיי אנשים עם מוגבלויות. הצטרפתי בשמחה, כי הסיפור שלי דומה להפליא לסיפורים שוורד רואה יום-יום."},{"t":"p","x":"חליתי כשהייתי נערה, אבל למגרש הגעתי כשהייתי בת יותר משלושים, מרוסקת נפשית ופיזית. מה שקרה אחר כך היה מהפך בקצב שלא דמיינתי – מה ששום טיפול נפשי או פיזיותרפיה לא הצליחו לעשות, הספורט עשה תוך חודשים ספורים."},{"t":"p","x":"כשעליתי לראשונה למגרש, למדתי על הכוח האדיר שנותן לי דווקא כיסא הגלגלים. כוח לראות איך הכיסא מוביל אותי לניצחונות. המיקוד שלי עבר מהשוני והנכות שלי לאינסטינקטים, לתשוקות, ליכולות. גיליתי שיש לי לב של ספורטאית ונשאבתי חזק לספורט תחרותי – שיחקתי יותר משבע שנים בענף רוגבי כיסאות גלגלים, ענף יחודי שנוצר עבור אנשים עם מגבלה ברגלים ובידיים - קוואדים. שם פשוט מצאתי את הקול האמיתי שלי."},{"t":"h2","x":"כשהכוח הפנימי מדבר"},{"t":"p","x":"\"כשאני רואה אותם מתרוממים – פיזית ונפשית – אני מבינה למה אני פה,\" ורד אומרת, והעיניים שלה נוצצות."},{"t":"p","x":"ורד עצמה היא ההוכחה הכי טובה לעוצמת השפעת הספורט על כולנו. \"הספורט נתן לי ביטחון כשהייתי ילדה שקטה שלא מצאה את עצמה,\" היא נזכרת. \"בבית הספר לא ממש הסתדרתי, אבל על המגרש הרגשתי שאני יכולה לעשות הכל. זה מה שמוביל אותי כל החיים.\""},{"t":"h2","x":"המסר האמיתי להורים"},{"t":"p","x":"יש משהו בספורט פראלימפי שמלמד לא רק לחיות, אלא למצוא את הקול הייחודי שלך מתוך ההמון ולהוביל אחרים. אמנם לא כל ילד או ילדה ירצו או יוכלו להיות אלופים פראלימפיים, וזה בסדר גמור – הספורט הוא כלי ולא מטרה."},{"t":"p","x":"וכמו שוורד אומרת בפשטות: \"אם אני יכולה, כל אחד ואחת יכולים. צריך לנסות – אף אחד לא חייב להיות אלוף אולימפי, מספיק לתת לעצמך הזדמנות ואתה תצליח.\""},{"t":"p","x":"לא צריך מחר לרוץ מרתון או להצטרף לנבחרת הלאומית – הילדים והילדות צריכים להרגיש את מה שוורד הרגישה כשהחזיקה מחבט טניס ביד, או כששמעה את הכדור המצלצל לראשונה. בכל ילד וילדה יש משהו חזק, ומגיע להם מקום מבלי להוכיח כלום לאף אחד חוץ מלעצמם. \"בסוף, זה לא רק ספורט,\" ורד מסכמת, \"זה להאמין שאת שווה, שיש לך את היכולת – וזה משהו שכל אחד ואחת מאיתנו מסוגלים לעשות.\""},{"t":"p","x":"אבל מבחינתי, השאלה האמיתית אינה מה הילדים שלנו יכולים לעשות – אלא מה אנחנו יכולים לעזור להם לגלות על עצמם, ללא קשר לשוני שלהם. צעד קטן על המגרש, אחיזה בכדור הם למעשה צעד להפנמה שהשוני או המגבלה הם למעשה נקודת הפתיחה לכוח ייחודי."},{"t":"p","x":"בתקווה שמכתב זה ייגע בלבך כפי שסיפורה של וורד נגע בלבי, דיאנה"}]},"השווי-שלי-בעולם":{"b":[{"t":"img","src":"ffb43f_d00cf464abac4fee80e72bd241dfecae~mv2.jpg","cap":"Photo by Amanda Jones on Unsplash"},{"t":"p","x":"לעיתים קרובות אנחנו מעריכות את השווי והערך שלנו לפי מדדים חיצוניים- התוצאות שלנו בתחרות, כמות הלייקים שקיבלנו באינסטגרם ודעות של אנשים עלינו. זה עלול להוביל למצב בו ספורטאית שניצחה בתחרות תרגיש על גג העולם, מאושרת, ואם הפסידה, תרגיש כישלון. כשהערך העצמי שלנו תלוי בתוצאה חיצונית אנחנו עלולות למצוא את עצמנו בחיים מאוד מטלטלים רגשית. בהרבה מהבתים כשהילדים חוזרים מבית הספר השאלה הראשונה שהם נשאלים היא מה הציון שהם קיבלו במבחן, ככה הם עשויים לחשוב שלא משנה כמה הם השקיעו, החכימו ולמדו בדרך אל המבחן אלא משנה מה הציון שקיבלו. אם הילדה קיבלה ציון טוב ההורים משבחים אותה והיא מרגישה אהובה ושמחה אך אם קיבלה ציון לא טוב הם יביעו אכזבה וביקורת והיא עשויה להרגיש טיפשה ואפילו תחושת כישלון."},{"t":"p","x":"אבל תארו לכן, איך זה היה לחיות בעולם בו הייתן רוצות את התוצאה אבל לא הייתן תלויות בה. רוצות לקבל מחיאות כפיים על התוצאה שלכן אבל אתן לא תלויות בהן בשביל להרגיש שוות. מצב בו אתן יודעות מה הערך שלכן וגם יודעות ששום תוצאה, ציון או לייק טיפשי לא יוכלו לשנות אותו. מצב כזה נותן הרבה כוח וחופש פעולה, כי כאשר את יודעת שהערך שלך לא תלוי בשום תוצאה, יש לך את החופש המוחלט לפעול ולממש את השאיפות, החלומות והרצונות החופשיים שלך. ספורטאית מוכרת סיפרה לי שבעבר הפסד היה שובר אותה, אחריו היא הרגישה בושה ותחושת כישלון עמוקה מה שהוביל אותה לפחד והימנעות מתחרויות. כשהיא בכל זאת התחרתה, הפחד להפסיד איים עליה ובאופן שיטת. היא חוותה התקף חרדה עצים שהתבטא בתחושת נימול בגפיים, קוצר נשימה ותחושת ניתוק. הביטויים הפיזיים לתחושת הפחד שחוותה שהיו אמורים כביכול להגן עליה מפני האיום הובילו לתוצאה ההפוכה והיא הפסידה. היא סיפרה לי שהמעגל הזה נמשך עד שהיא עשתה עבודת עומק, שבסופה, כיום, הפחד להפסיד לא מנהל אותה והיא חופשייה לבטא את היכולות שלה בתחרות. היא גילתה לי שאחת הדרכים שהכי עזרו לה היא שהתחילה להעריך את עצמה על המאמץ שהיא משקיעה בתחרויות ולא על התוצאה הסופית. תחילה אני מודה שהייתי סקפטית, אך ברגע שנתתי לזה הזדמנות ולמרות שזה לא בא לי בטבעיות, אמרתי לעצמי מילים טובות על המאמץ וגיליתי שהפחדים שלי ״להיכשל״ פחות ופחות מנהלים אותי."},{"t":"p","x":"כמה פעמים הגעתן הביתה אחרי יום שנחשב מוצלח אבל ידעתן שיכלתן לתת יותר? ומנגד, כמה פעמים הגעתן אחרי יום גרוע אבל לא הייתן משנות דבר בעשייה שלכן? אין לנו שליטה על התוצאה ולכן, עלינו לתלות את הערך העצמי שלנו באומץ שלנו. ייתכן שתגידו שרק אם הפעולה תצליח - ניצחתי, אך האמת היא שאם ניגשת באומץ לפעולה - ניצחת. ההחלטה לשים את המשקל והמיקוד על הדרך שלכן, ולא על התוצאה, תשפיע מאוד על תפיסת הערך העצמי שלכן. כך, גם כשתנצחי, את תביני שהניצחון הזה לא הפך אותך לאדם טוב יותר וכשתפסידי, את לא תיפלי לקרשים. זה לחיות במקום מאוזן, עם הערכה עצמית שאינה תלויה בדבר חיצוני, וכשהשווי שלי לא תלוי בשום דבר, אני יותר משוחררת לחיות את החיים שלי בעולם שלנו במלוא העוצמה והפוטנציאל שיש לי."},{"t":"p","x":"לעיתים קרובות אנחנו מונעות מהפחד לא להפסיד, אנחנו נימנע מלקחת סיכון אבל לא נדע לאן יכולנו להגיע. זו הספורטאית שלא תעז לקחת זריקה חשובה, עורכת הדין שלא תשווק את עצמה. יכול להיות שכן נשאף לתוצאה וניקח סיכון אבל אחרי שנשיג את התוצאה שרצינו, נהיה עסוקות כל כך בלשמר את הניצחון ולא להפסיד אותו שנחזור להימנע מלקחת סיכון. ברמה הגבוהה ביותר אנחנו נחייה בעולם כדי להביא את עצמנו לידי ביטוי במקסימום, לא נהיה מונעות מהפחד אלא מהנסיון להגשים את חלומותינו, רצונותינו ולמקסם את הפוטנציאל שלנו."},{"t":"p","x":"כדי לדעת אם את מונעת מפחד להפסיד תשאלי את עצמך: 'אם התוצאה לא הייתה רלוונטית, מה הייתי עושה עכשיו?' או לחילופין: 'היכן הייתי נמצאת ואילו אנשים היו מקיפים אותי?' יכול להיות שכשתעני לעצמך על השאלות האלו תגלי שאת לא נמצאת במקום שעושה לך טוב, שאת מתעלמת מהרצונות והמטרות שלך בגלל שאת מפחדת לאבד את הערך שלך, אבל כאשר תדעי שהערך שלך לא תלוי בשום תוצאה יהיה לך החופש המוחלט לפעול ולממש את השאיפות, החלומות והרצונות החופשיים שלך, וכדי לדעת זאת, הגיע הזמן שתתמקדי בדרך ובמאמץ שלך אל התוצאה אליה את מייחלת."},{"t":"p","x":"אולי תוכלו להסכים איתי שיש תפיסה מוזרה כזאת שנולדנו עם החובה להוכיח, שחסר לנו משהו שאנחנו צריכות למלא עם תוצאות והישגים שיתנו הצדקה לקיום שלנו. השאלה אם זה יכול להחזיק מים. תנסו לחשוב אם אחרי שהשגתן תוצאה מסוימת זה מילא את התחושה שתיארתי, יכול להיות שכן, אבל רק לזמן קצר. אם אתן לא תעריכו את עצמכן כנשים שאתן, שום הכרה בעולם לא תוכל לשנות את זה באמת!"}]},"לרוץ-בלי-לעצור":{"b":[{"t":"p","x":"**מאור טיורי על הצלחה ספורטיבית ואקדמית ועל השקעה בחלומות. \"העובדה שנשארתי בארצות הברית עזרה לי להתקדם גם מבחינה ספורטיבית וגם מבחינה אישית, ויצאתי עם תואר ביד\"**"},{"t":"img","src":"ffb43f_a0a467ce36b342d0b15ffa175413d3ed~mv2.jpeg","cap":""},{"t":"p","x":"**מה גורם לנערה בת 11 לרוץ מהר יותר מכולם, ולהפוך לאחת הספורטאיות הבולטות בישראל? הסיפור של מאור טיורי, אצנית אולימפית שכבשה שלוש אולימפיאדות, יגרום לכן לשאול: איך היא עשתה את זה – ומה אני יכולה ללמוד ממנה?**"},{"t":"p","x":"**כמי שחוקרת את הקשר בין ספורט לקריירה, אני רואה במאור דוגמה מושלמת לכך שבספורט יש את הכוח לחשוף את הפוטנציאל שלך – לא רק על מסלול, אלא גם למימושו מחוצה לו ברמת הקריירה. הסיפור שלה הוא לא רק על ריצה מהירה, אלא על איך עבודה קשה, התמדה וחשיבה יצירתית יכולות להוביל אותך לגבהים חדשים. **"},{"t":"p","x":"**אז קחי נשימה עמוקה, ותתכונני להתרשם.**"},{"t":"p","x":"**המרד שהוביל לשלוש אולימפיאדות**"},{"t":"p","x":"\"עבודה קשה, התמדה ויכולת להסתגל – זה מה שהביא אותי לאן שהגעתי\" אומרת מאור טיורי, ששמה הפך לשם נרדף להצלחה באתלטיקה הישראלית. הכל התחיל בגיל 11, כשמורה לספורט בבית הספר היסודי זיהה את הכישרון שלה, \"הוא דחף אותי להתחרות בשביל בית הספר\" היא מספרת, \"ניצחתי את התחרות הראשונה, וככה נשאבתי לעולם הספורט\"."},{"t":"p","x":"מאז, המסע של מאור היה רצוף ניצחונות, שיאים ואליפויות. אבל מה שהופך את הסיפור שלה ליוצא דופן הם לא רק ההישגים, אלא הדרך שבה היא סירבה לבחור בין החלום האולימפי שלה לבין בניית עתידה. היא מצאה דרך לשלב בין השניים – ולהוכיח שספורט יכול להיות לא רק תחרות, אלא גם פלטפורמה לצמיחה אישית ומקצועית."},{"t":"p","x":"**הלב נקרע לשניים**"},{"t":"p","x":"הדרך להצלחה ספורטיבית מגיעה לעיתים עם דילמות לא פשוטות. נערות צעירות מתמודדות עם מסר סמוי: או שאת משקיעה בלימודים ובקריירה, או שאת הולכת עד הסוף בספורט. מאור, שהייתה תלמידה שאפתנית וספורטאית מחויבת, הרגישה את המתח הזה על בשרה."},{"t":"p","x":"\"בתיכון הייתי די טוטאלית\" היא מודה. \"הפוקוס שלי היה על לימודים וספורט, ולא נשאר לי הרבה זמן לדברים אחרים. לא הלכתי למסיבות או ביליתי כמו הילדים האחרים\". היו רגעים שבהם הרגישה שונה, ואפילו בודדה, כשהיא נאבקת לאזן בין השאיפות שלה כספורטאית לבין הרצון להצליח בלימודים. אבל במקום לוותר, היא בחרה להתמיד – ולמצוא דרך משלה."},{"t":"p","x":"**הצעד הגורלי מעבר לאוקיינוס**"},{"t":"p","x":"אחרי השירות הצבאי כמורה חיילת, מאור קיבלה החלטה ששינתה את חייה: היא טסה לארצות הברית ללמוד במכללה עם מלגת ספורט מלאה. \"זו הייתה ההחלטה הכי נכונה שעשיתי,\" היא אומרת. \"שמעתי על הדרך הזו מאתלטים אחרים, ובזמנו לא היו הרבה ישראלים בקולג'ים. ידעתי שאם אני רוצה להתקדם, זו ההזדמנות שלי.\""},{"t":"p","x":"במהלך השירות הצבאי, היא למדה למבחני הקבלה האמריקאים ויצרה קשר עם מאמנים באוניברסיטאות שונות. \"זה היה סוג של מזל שהגעתי לאוניברסיטה שלא שברה אותי, אלא פיתחה אותי\" היא משתפת. בארה\"ב, היא גילתה עולם שבו ספורט והשכלה לא סותרים זה את זה, אלא משלימים. זו הייתה נקודת מפנה עבורה."},{"t":"p","x":"**שני מסלולים, חלום אחד**"},{"t":"p","x":"בניגוד לאתגרים בישראל, המערכת האמריקאית בנויה לתמוך בספורטאים שרוצים להצליח גם במסלול וגם באקדמיה. \"הכל היה מותאם\" מסבירה מאור, \"המלגה המלאה נתנה לי את כל מה שהייתי צריכה. כמובן שהיו חובות כסטודנטית, אבל האוניברסיטה התחשבה בלוח התחרויות שלנו.\""},{"t":"p","x":"התכונות שהפכו את מאור לספורטאית יוצאת דופן – משמעת עצמית, עבודה קשה והתמדה – היו גם אלה שסייעו לה להצטיין בלימודים. היא למדה מדעי הספורט והאימון, וייצגה את האוניברסיטה בליגת המכללות האמריקאית במרוצי שדה ומסלול. \"המערכת שם קשוחה, אבל המאמנים שמרו עלינו\" היא אומרת, \"הגישה הזו אפשרה לי לפרוח.\""},{"t":"p","x":"לאחר סיום הלימודים, מאור נשארה בארצות הברית לעשור נוסף, שם המשיכה להתפתח כאצנית מקצועית. במקביל, היא עבדה בסוכנות ליחסי ציבור, שתמכה בה כאשת מקצוע וכספורטאית. \"הייתה לי עבודה ממש טובה, והם היו גמישים עם לוח התחרויות שלי\" היא משתפת."},{"t":"p","x":"התוצאות מדברות בעד עצמן: מאור השתתפה בשלוש אולימפיאדות – הישג נדיר לספורטאית ישראלית. אבל היא לא עצרה שם. לפני כמה ימים, היא כבשה עוד פסגה, כשהגיעה רביעית באליפות אירופה, ביחד עם חברתה לנבחרת, לונה צ'מטאי והראתה שהיא עדיין בשיאה."},{"t":"p","x":"**רגע היסטורי באליפות אירופה**"},{"t":"p","x":"באליפות אירופה האחרונה, מאור הגיעה להישג מרשים שהותיר אותה עם תחושות מעורבות של שמחה ושברון לב. \"פספסתי מדליית ארד, שיכלה להפוך להיסטורית עבורי\" היא מספרת, \"אבל אני גאה בריצה שנתתי ועל המיקום ההיסטורי שלי באליפות בינלאומית.\""},{"t":"p","x":"יחד עם לונה צ'מטאי-סלפטר והלן וולפסון, מאור הובילה את הנשים הישראלית למדליית כסף קבוצתית – הישג חסר תקדים באתלטיקה הישראלית. ההישג הזה, לדבריה, מחזק את האמונה שלה שהיא יכולה להמשיך לשפר ו\"לחלום בגדול\"."},{"t":"p","x":"התוכניות שלה לעתיד כבר מוכנות: התאוששות מהמרתון, השתתפות בתחרויות קצרות, אליפות עולם במרתון, ומרתון מהיר שיאפשר לה להציג את הכושר שלה במלואו. \"אני רוצה להמשיך במגמת ההתקדמות\" היא מוסיפה עם מוטיבציה מידבקת."},{"t":"p","x":"**לא לוותר על אף חלום**"},{"t":"p","x":"המסע של מאור לא היה קל, והיא בחרה בדרך שדרשה ויתורים, כולל יציבות כלכלית מסוימת. אבל היא לא רואה בזה הקרבה, אלא השקעה בחלומות שלה. \"העובדה שנשארתי בארצות הברית עזרה לי להתקדם גם מבחינה ספורטיבית וגם מבחינה אישית, ויצאתי עם תואר ביד\" היא אומרת,"},{"t":"p","x":"\"בישראל, מסלול כזה הוא מאתגר יותר, אבל אני מאמינה שכל אחת יכולה למצוא את הדרך שלה.\""},{"t":"p","x":"היא רואה הזדמנות עצומה בספורט הישראלי, במיוחד עבור נשים. \"אנחנו מפספסות ספורטאיות מבריקות כי אין מספיק תמיכה\", היא אומרת, אבל במקום להתעכב על המכשולים, היא מציעה פתרונות: מסלולי מלגות מותאמים, גמישות אקדמית, שיתופי פעולה בין איגודי ספורט למוסדות אקדמיים, והקמת קרנות תמיכה. מעל הכל, היא מדגישה את החשיבות של חשיבה יזמית: \"ספורט הוא לא רק תחרות – הוא בית ספר לחיים ולקריירה.\""},{"t":"p","x":"**הצעד הראשון שלך**"},{"t":"p","x":"מאור משתפת כמה עצות מעשיות לנערות שחולמות בגדול:"},{"t":"ul","x":["**שאלו שאלות**: \"דברו עם ספורטאיות שכבר עשו את הדרך הזו. המליצו לי, ואמרו לי שזו הדרך להתקדם.\"","**התכוננו מראש**: \"למדתי למבחני כניסה בזמן השירות הצבאי ויצרתי קשר עם מאמנים.\"","**אל תפחדו מאתגרים**: \"בהתחלה התלבטתי, אבל בסוף החלטתי ללכת על זה.\"","**חפשו את המקום הנכון**: \"מצאתי אוניברסיטה שפיתחה אותי, וזה עשה את ההבדל.\"","**בנו נוכחות ברשתות**: \"שתפו את המסע שלכן – זה פותח דלתות.\"","**צרו קשרים**: \"התחברו לקהילות שיכולות לתמוך בכן.\"",""]},{"t":"p","x":"**מחר חדש לספורט הנשי בישראל**"},{"t":"p","x":"העולם משתנה, וספורטאיות כמו מאור טיורי מראות שאפשר ליצור הזדמנויות במקום לחכות להן. המסלול האמריקאי עבד עבורה, אבל החלום הגדול יותר הוא לבנות מודל ישראלי – כזה שמשלב ספורט, השכלה וקריירה בצורה שתאפשר לכל ספורטאית למצות את הפוטנציאל שלה."},{"t":"p","x":"ספורט הוא לא רק דרך להגיע לפודיום, אלא כלי לגלות את הכוח הפנימי שלך כאישה. נצלי את זה. מאור טיורי היא ההוכחה: תחלמי בגדול ותמצאי את הדרך שלך להצליח – במסלול וגם מחוצה לו."}]},"אירנה-במושבה-הישראלית-בגרמניה":{"b":[{"t":"p","x":"בקבוצה בליגת העל הגרמנית התמקמה מושבה של שחקניות ישראליות. ארבע (!) שחקניות ישראליות שמצאו את עצמן יחד, על אדמת גרמניה, חיות את החלום. עבור אירנה קוזנצוב, בת 19 בלבד, זוהי הגשמת חלום אמיתית. מי שהתחילה את דרכה בגיל שש במדשאות בית ספר ארלוזרוב בחדרה, כשהייתה משחקת עם הבנים בהפסקות, התקבלה בהמשך לאקדמיה בוינגייט והחליטה שהדשא הוא הבית, כובשת את גרמניה ובגדול."},{"t":"p","x":"איך עושה ילדה מחדרה את הדרך עד לליגה הגרמנית החזקה?"},{"t":"p","x":"\"היה לנו משחק נגד גרמניה, עשיתי שם עבודה טובה הגנתית טובה נגד שחקניות שנחשבו כמה רמות מעליי\" מספרת אירנה \"ואחריו קיבלתי הודעה באינסטגרם מסקאוטר של הקבוצה. לא היה לי מושג שבאים לבחון אותנו\"."},{"t":"p","x":"הקשר עם הסקאוטר הוביל למבחנים בקבוצת \"טורבינה פוטסדאם\" שהובילו אותה הישר לתוך סגל הקבוצה ולקדנציה הראשונה שלה מעבר לים. בהתחלה הריחוק מהמשפחה והחברים היה קשה, אבל סדר היום הטובעני, כמו גם העובדה שיחד איתה הגיעו עוד שלוש שחקניות ישראליות, הפכו את החוויה לקלה הרבה יותר ואיפשרו לשחקנית הצעירה למצוא את הכוחות שבה מחדש \"יש לי כל כך הרבה אתגרים, בין אם זה בכדורגל ובין אם זה בחיים האישיים שאני פותרת בכוחות עצמי\" מספרת אירנה על התחושה המעצימה שהסיטואציה הביאה איתה.  היא מודה שכשהיא מגיעה לחופשה בארץ היא שואבת מהמשפחה והחברים המון אנרגיה שנותנת לה את כל הכוח שהיא צריכה עד הפעם הבאה."},{"t":"p","x":"בקבוצה, כאמור משחקות ארבע ישראליות, אירנה, נועה, שחר, ומריה. סיטואציה נדירה בכל קנה מידה (מישהו מתאר לעצמו מצב בו בבונדסליגה יש ארבעה שחקני כדורגל ישראלים באותה קבוצה?). מה שעוזר לתחושת הביטחון שלהן וליכולת שלהן לפרוח ביחד. \"אנחנו תומכות אחת בשניה. יש לנו קשר טוב וזה נותן כוח באימונים\" מודה אירנה \"כשאנחנו לא רוצות שיבינו, אנחנו פשוט עוברות לעברית\". הארבע הן חלק בלתי נפרד בהווי של הקבוצה הגרמנית \"כשאנחנו נכנסות לחדר הלבשה מדברות עברית אנחנו כל כך רעשניות וקולניות שאומרים 'הנה הישראליות הגיעו' אנחנו מדברות, צוחקות ונהנות\". יש להן גם קבוצת וואטסאפ רק שלהן, שם הן בין היתר קובעות מתי בפעם הבאה יישבו לשקשוקה."},{"t":"p","x":"אז מה בעצם גורם לשחקנית ישראלית צעירה לעבור לשחק בחו\"ל?"},{"t":"p","x":"קוזנצוב מודה שהתנאים שונים והיכולת להתרכז בכדורגל היא כמעט אבסולוטית \"אנחנו מקבלות רכב, דירה ומשכורת\" היא מסבירה \"אומנם יש את זה גם בארץ, אבל בגרמניה רמת הכדורגל שונה לגמרי. זה משחק הרבה יותר אינטנסיבי\". כדי לעמוד בקצב הן משחקות הרבה יותר כדורגל, מתאמנות יותר בחדר כושר, \"הבנות פה הרבה יותר חזקות, מהירות ואגרסיביות והקצב של המשחק עצמו הרבה יותר גבוה. אם לדוגמה השחקניות בארץ יותר מניעות את הכדור בפסים, כאן נותנות כדור ארוך ורצות וזה הרבה יותר קשה פיזית\"."},{"t":"p","x":"עבור קוזנצוב שהגשימה את החלום לשחק באירופה, הרעב רק נפתח. להיות שחקנית זרה זאת מחוייבות שדורשת ממנה להוכיח את עצמה על המגרש בכל פעם שהיא דורכת על הדשא \"כשאת מגיעה מישראל קבוצות באירופה מטילות בך ספק. אנחנו לא נחשבות לנבחרת חזרה, לא הגענו רחוק במפעלים האירופים והיבשת (אירופה) מפוצצת בשחקניות מוכשרות\" היא משתפת קצת בהתמודדות עם המעמד \"זאת הרגשה שמלווה אותי כל הזמן, אני אומרת לעצמי שאני חייבת לעבוד הרבה יותר קשה מהבנות המקומיות כי אני שחקנית זרה\"."},{"t":"p","x":"העבודה הקשה של אירנה בהחלט משתלמת לה. לאחרונה היא הבקיעה את הגול הראשון שלה במדי הנבחרת הבוגרת ונראה שלגול הייתה משמעות עמוקה עבורה \"אחרי הגול דבר ראשון בכיתי. הרבה זמן רציתי להבקיע גול בנבחרת הבוגרת, זה מביא לי כל כך הרבה גאווה. הגול הזה נתן לי כל כך הרבה כוח ורגש ופשוט שמחתי עד כדי כך שבכיתי מהתרגשות ואושר\". אחרי תקופה לא פשוטה מבחינתה והמון סימני שאלה, הגול הזה היה סימן הקריאה שקוזנצוב חיכתה לו שיסמן לה שהיא בדרך הנכונה. \"לאחרונה יש לי מחשבות על העתיד, האם אני אצליח להגיע לרמות הגבוהות שאליהן שאפתי. התחילו לי גם התכווצויות שמנעו ממני לסיים משחק של תשעים דקות, אז תהיתי איך אני אצילח ברמות הגבוהות כשהרמת אינטניסיביות יותר קשה והבריאות שלי לא כזו טובה.  החלטתי לקחת את עצמי בידיים, ללכת לתזונאית להשקיע יותר מאמץ מעבר לאימונים. המאמצים"},{"t":"p","x":"השתלמו והצלחתי לסיים תשעים דקות בנבחרת, להבקיע את הגול הזה, תחושת התקווה והתשוקה חזרו אליי והביטחון העצמי עלה. הרגשתי שהייתי צריכה את הגול הזה שיאמר לי תילחמי! תילחמי על החלום שלך.\""},{"t":"p","x":"אירנה עם הפנים קדימה, ונראה שהרוח הגבית שהגול הזה נתן לה, ביחד עם הרעב הטבעי שאיתו היא מגיעה, עוזר לה לסמן את הפסגה הבאה אותה היא הולכת לכבוש \"אני מרגישה שהתפתחתי המון והמטרה הבאה היא לשחק במועדון יותר גדול. אני כבר מגיעה כשחקנית יותר בוגרת ואני מרגישה שיש לי הרבה מה לתת\". ובינתיים, היא תמשיך לעשות חיל במושבה הישראלית בגרמניה תוך כדי שהיא סוללת לה את הדרך לפסגה הבאה."}]},"בשיא-הסטייל-על-מגרש-הכדורגל-הילדה-על-העקבים-שכבשה-את-הדשא":{"b":[{"t":"p","x":"**הכדורגל שלא נרשם בדפי ההיסטוריה  **"},{"t":"img","src":"ffb43f_a36f2181074b4681a7788f32008b637b~mv2.jpg","cap":"Photo by Nima Sarram on Unsplash"},{"t":"p","x":"כשהייתה ילדה קטנה, היא לא דמיינה שתשחק כדורגל. היא לא הייתה \"טומבוי\" שרצה עם הבנים בחצר אחרי בית הספר, ולא ראתה את עצמה מתאימה לסטיגמה של הספורטאית הגברית. היא אהבה להתלבש יפה, לטפח את הציפורניים, להיות הילדה הנשית שמושכת מבטים. אבל משהו בכדורגל קרא לה – אולי זה היה אבא שלה, שחקן בעברו, או אולי אחיותיה הגדולות שפתחו לה צוהר לעולם הזה. \"תמיד שיחקתי גם עם בנים וגם עם בנות,\" היא מספרת, \"לא הגדרתי את עצמי לא לזה ולא לזה.\""},{"t":"p","x":"הסיפור שלה הוא לא רק על כדורגל – הוא על נשיות ששוברת מחסומים, על ילדה שמצאה את מקומה על הדשא בלי לוותר על מי שהיא. זו עדות לכוחה של הזהות האישית בעולם שפעם לא ידע איך לקבל אותה."},{"t":"p","x":"**כדורגל במשפחה**"},{"t":"p","x":"הכל התחיל בבית. \"אבא שלי היה שחקן כדורגל בצעירותו,\" היא משתפת. \"זה משהו שנחל במשפחה.\" כשהייתה בת שבע בערך, אחותה הגדולה התחילה לשחק, והמשפחה – שבה הספורט תמיד היה חלק מהדי.אן.איי – התגייסה לתמוך. התמיכה לא הגיעה מיד. \"אף אחד לא ממש התנגד, אבל גם לא ממש תמך. לא ידעו מה זה כדורגל נשים. אמרו, 'אוקיי, אז היא הולכת לשחק עם כמה חברות'.\""},{"t":"p","x":"\"לא האמינו שיש באמת קבוצות נשים,\" היא מסבירה. אבל הכל השתנה כשדוד שלה ראה את אחותה משחקת ואמר לאבא שלה: \"היא ממש טובה.\""},{"t":"p","x":"**הילדה הנשית במגרש – להתבלט ולהתקבל**"},{"t":"p","x":"בגיל 14 היא כבר לא רק צפתה מהצד. היא הצטרפה לקבוצה בתל אביב, אותה קבוצה שבה שיחקה אחותה בילדותה. ההורים שלה, שכבר היו מחויבים לספורט, ליוו אותה לכל אימון ומשחק. אבל המגרש לא תמיד היה מקום מסביר פנים. \"בהתחלה היה לי יותר קשה להתחבר לבנות בקבוצה,\" היא מודה. \"הן היו בווייב אחר, ואני הייתי קצת יוצאת דופן.\""},{"t":"p","x":"היא לא התאימה לתבנית. היא הגיעה לאימונים אחרי שהחליפה בגדים באוטו – מבגדים יפים שלבשה לבית הספר לבגדי ספורט. \"תמיד אהבתי להתלבש,\" היא מספרת, \"והייתי היחידה שם עם ציפורניים מסודרות.\" התגובות סביבה היו מעורבות, והיא הרגישה את המבטים. עם הזמן, היא למדה לעמוד על שלה. \"אמרתי לעצמי, 'כן, זה הבגדים שלי, אני כזו'.\""},{"t":"p","x":"האתגר לא היה רק חברתי – הוא היה אישי. \"כשאת ילדה, לפעמים יש סטיגמה שמי שמשחקת היא גברית,\" היא אומרת. \"אבל אני למדתי שאפשר להיות גם וגם – נשית, רגישה, וגם חזקה וטובה על המגרש.\""},{"t":"p","x":"**החסמים שכמעט עצרו אותה והנחישות שניצחה**"},{"t":"p","x":"הדרך שלה לא הייתה קלה. כשחקנית בליגה הראשונה, היא התאמנה ארבע פעמים בשבוע, שיחקה בסופי שבוע, וניסתה לאזן בין עבודה, חיים אישיים ותשוקה לספורט. \"זה קשה לנהל הכל,\" היא מודה. \"עבדתי בבוקר, חזרתי הביתה עייפה, והיה אימון. לפעמים חזרתי ב-11-12 בלילה ממשחק, ולא ישנתי.\" הכסף לא זרם כמו אצל הגברים – \"לא יכולתי לצמצם עבודה באופן משמעותי.\""},{"t":"p","x":"אבל החסם הגדול ביותר לא היה כלכלי – הוא היה חברתי. \"כשיצאתי עם גברים, הם היו שואלים אותי, 'מה, באמת שיחקת כדורגל?'\" היא נזכרת. השאלה הזו חזרה שוב ושוב, כאילו נשיות וכדורגל לא יכולים לדור בכפיפה אחת. \"הם היו אומרים, 'את הכי נשית, את הכי רגישה, איך שחקת?'\" היא לקחה את זה בצחוק, אבל בתוך הקבוצה היא הרגישה לפעמים זרה."},{"t":"p","x":"אז היא בחרה להילחם – לא עם אגרופים, אלא עם אישיות. \"למדתי להתמודד עם זה ולהגיד, 'גם אני כאן'. אני יכולה להיות נשית ועדיין לשחק טוב.\""},{"t":"p","x":"**השער הגדול שמשנה את המשחק**"},{"t":"p","x":"היום היא כבר לא משחקת, אבל המגרש עדיין חלק ממנה. כרכזת ענפי כדור קבוצתיים באתנה, היא פועלת להביא יותר ילדות ונערות למשחק שהיא כל כך אהבה. \"אני רואה את ההתקדמות מבפנים, וזה מדהים אותי\" היא אומרת, והגאווה בקולה מחממת את הלב. מהילדה שרצה סביב המגרש כמביאת כדורים, היא הפכה למי שפותחת שערים לנערות אחרות – כי היא יודעת שגם להן מגיע מקום והזדמנות שווה. הסיפור שלה הוא קריאה לכל ילדה: תשחקי בלי להתנצל, כי כשאת מביאה את עצמך למגרש, את משנה את המשחק."}]},"מאמנות-את-המערכת-מאמנות-הישג-מפסיקות-להתנצל-על-השאיפות":{"b":[{"t":"p","x":"\"כשבדקנו את נתוני המשחקים האולימפיים בפריז 2024, יש לנו שמונה מדליסטיות אולימפיות (שלוש ספורטאיות בענף אישי ועוד חמש בקבוצתי) וכמעט כולן עברו בשלב כלשהו דרך תוכנית אתנה טופ טים\", מספרת תכלת אדלמן, רכזת התוכנית. \"זה מראה שעבודה שיטתית ולאורך זמן מוכיחה את עצמה.\""},{"t":"p","x":"**המהפכה השקטה של אתנה -המרכז לקידום ספורט נשים בישראל**"},{"t":"p","x":"תוכנית אתנה טופ טים היא תוכנית הישגית ייחודית של אתנה בוועד האולימפי. התוכנית עברה שינויים משמעותיים מאז הקמתה לפני כעשרים שנה. \"אם נחזור עשרים שנה אחורה,\" מספרת אדלמן, \"היו מעט מאוד ספורטאיות הישג בארץ. התוכנית התמקדה בדרג א' וב', והיום הספורטאיות המובילות כבר ממומנות כמעט באופן מלא להכנה והגעה למשחקים האולימפיים.\" הדבר הבסיסי והחיוני ביותר שהתוכנית מספקת הוא המעטפת הרפואית. \"זה הדבר הראשון שמוותרים עליו כשאין כסף,\" מסבירה אדלמן. \"אם יש לי פציעה ביד או ברגל והיא לא נראית רצינית, הכי קל לוותר על הטיפול כדי לצאת לתחרות בחו\"ל. אבל עם תמיכה מקצועית, אפשר לעשות גם וגם, והפוטנציאל להצליח גדל משמעותית.\""},{"t":"p","x":"במהלך השנים, התוכנית שינתה את אופי הסיוע מאישי לנבחרתי. \"היום הסיוע ניתן הרבה פעמים כסיוע נבחרתי,\" מסבירה אדלמן. \"זה מאפשר לנו להגיע ליותר ספורטאיות, כולל אלה שבדרך לסגל אבל עדיין לא שם. בין אם זה סדנאות, פעילות רוחבית, תוספת שעות לאנשי מקצוע, מאמני כושר או ליווי מנטלי.\""},{"t":"p","x":"**האתגר הבא: המחסור במאמנות בדרג העליון**"},{"t":"p","x":"אבל ההצלחה בזירת הספורטאיות רק מדגישה את האתגר הבא: המחסור החמור במאמנות בדרג העליון. \"העבודה היא כל כך תובענית,\" מסבירה אדלמן, \"שגם הגברים לא בטוחים איך לשלב את זה עם המשפחה. אני מכירה מאמנים בכירים שבשלב מסוים אמרו 'עד כאן, אנחנו לא מסוגלים לנהל חיי משפחה כמו שאנחנו רוצים.' כמובן שאצל נשים החסם הזה הרבה יותר משמעותי גם מבחינה אבולוציונית וגם עדיין ציפייה חברתית בארץ הרבה יותר ממקומות אחרים בעולם.\""},{"t":"p","x":"תכלת סיפרה שיש מאמנות שנוח להן איפה שהן. הבעיה היא שהסטיגמות הישנות מונעות להתקדם מאלה שרוצות לאמן נבחרת. כדי שמאמנת תצליח, היא חייבת לא רק את העידוד המילולי והערכה מצד האיגוד, אלא גם עידוד שמתבטא בהשתלמויות, והכי חשוב במשכורת שווה לזו של מאמן באותו התפקיד. הופתעתי ממקרה מאיר עיניים: \"היה איגוד שיכול היה לשלוח מאמנת להשתלמות בחו\"ל. כשהם נשאלו למה לא הציעו את התפקיד למאמנת מתאימה מסוימת, התשובה הייתה 'יש לה ילדה קטנה בבית, כנראה שהיא לא תרצה' - והם אפילו לא שאלו אותה. רק לאחר שנשאלו על כך החליטו להציע בכל זאת.\" מודעות היא חלק גדול מהפתרון ומחובתם של האיגודים לפתוח הזדמנויות גם למאמנות. עם זאת אדלמן מציינת שגם בעולם לא רואים הרבה מאמנות ברמות הגבוהות, אם כי בחלק מהענפים יש התקדמות בשנים האחרונות."},{"t":"p","x":"**הפתרון היזמי**"},{"t":"p","x":"וכאן מגיע החיבור ההדוק בין עולם היזמות לספורט. אתנה טופ טים מנסה לסייע לאיגודים שמעסיקים מאמנות בנבחרות, אבל זה מעלה דילמה מורכבת. \"הרבה שנים דנו בשאלה האם הסיוע שלנו בשכר למאמנות משיג את המטרה,\" מסבירה אדלמן. \"האם זה גורם לאיגוד להשאיר אותן ולהביא מאמנות נוספות, או שאנחנו בעצם מנציחות מצב שבו האיגוד משלם למאמנת פחות ומקבל השלמת הכנסה מאיתנו?\""},{"t":"p","x":"**הדרך לשינוי**"},{"t":"p","x":"בשיחה עם תכלת זיהיתי שלוש דרכים עיקריות שבהן חשיבה יזמית יכולה לקדם מאמנות ספורט:"},{"t":"p","x":"1. יצירת מעגלי השפעה והזדמנויות:"},{"t":"p","x":"\"חלק מהפתרון זה להדהד את הרצון שלך להיות מאמנת ברמה גבוהה יותר כל הזמן,\" אומרת אדלמן. \"זה כמו כשאת מחפשת דירה או רכב - ברגע שאת מתחילה לדבר על זה עם החברים והסביבה, זה יושב להם בראש. כשיראו שיש הזדמנות, יזכרו לפנות אלייך.\""},{"t":"p","x":"2. פיתוח מנהיגות ומיומנויות רחבות:"},{"t":"p","x":"\"להיות מאמנת זה לא רק להיות הכי טובה מבחינה מקצועית בענף שלך,\" מדגישה אדלמן. \"זה גם לעשות קורסים שקשורים לליווי מנטלי, לאימון גופני, או כל דבר שמוסיף ערך ולגישה שלך לאימון.\" לדבריה, \"מי שמגיע לאמן ברמות הגבוהות יותר תמיד מביא איתו ידע רחב בתחומים נוספים כמו ניהול, NLP, יזמות - זה עוזר לפתוח את החשיבה ולהתפתח אישית.\""},{"t":"p","x":"3. מודעות והתפתחות מתמדת:"},{"t":"p","x":"\"אחד הדברים החשובים ביותר הוא לבדוק דרכים להתקדם ולדברר את הרצון שלך לאיגודים ולמועדון,\" מסבירה אדלמן. \"לא כל המאמנות יודעות שיש את האופציות האלה, והן בכלל לא הולכות ואומרות את זה.\" היא ממליצה להיות נוכחות בכל הזדמנות להתפתחות מקצועית שהאיגוד מציע."},{"t":"p","x":"\"אנחנו צריכות להראות שיש דרך,\" מסכמת אדלמן. \"יש לנו מאמנות שהקימו משפחה, שמאמנות ברמה הגבוהה ביותר, שטסות לחו\"ל להרבה מאוד ימים בשנה. למי שבאמת רוצה את זה - היא יכולה וצריכה להיות שם.\" המסר ברור: יש פה הזדמנות לשינוי אמיתי וכולם צריכים להיות חלק ממנו."},{"t":"p","x":"**מתחילות לקחת מקום**"},{"t":"p","x":"לסיכום, ספורטאיות ומאמנות, דברו על השאיפות שלכן בקול רם! השתתפו בכל השתלמות והכשרה אפשרית. צרו קשרים עם מאמנות אחרות. אל תניחו שמשהו לא אפשרי בגלל אילוצים - תנו לעצמכן את ההזדמנות. הדרך למצוינות על המגרש לעולם לא מסתיימת! יחד, נוכל ליצור מציאות חדשה בספורט הישראלי - כזו שבה מאמנות לא רק משתתפות במשחק, אלא קובעות את ה"},{"t":"p","x":"חוקים ומובילות אותו קדימה."}]},"קלפים-של-מנצחת-ליהיא-בן-דוד-מדליסטית-אולימפית":{"b":[{"t":"p","x":"**ליהיא בן דוד היא מדליסטית פראלימפית מפריז והשראה עצומה. **פגשתי אותה לראשונה במחנה ספורט לנוער עם לקויות ראייה ועיוורון המתקיים בבית חינוך עיוורים בירושלים, שתינו הגענו כמאמנות: ליהיא מענף הכדור שער ואני מענף הג׳ודו. ראיתי איך היא לא נותנת ללקות ראיה לעצור אותה, עם כריזמטיות מעוררת השראה."},{"t":"p","x":"ליהיא בת ה-29, היא שחקנית נבחרת ישראל בכדור שער ומדורגת ראשונה בעולם אשר נולדה עם לקות ראייה גנטית. מאז שהיא זוכרת את עצמה החיים שלה ושל משפחתה סבבו סביב ספורט. ״תמיד היינו בשכונה עם כדור״ היא מספרת. הכל התחבר יום אחד כשפגשה בקייטנה שחקנית כדור שער אחרת: ״היא הציעה לי לבוא לנסות את הספורט וככה התחילה הדרך שלי בענף״."},{"t":"p","x":"**ללקות ראייה היא מתייחסת בצורה שכולנו יכולים ללמוד ממנה: **״ההתייחסות שלי ללקות הראייה היא לא כחיסרון ולא כמגבלה. זה המצב, זה מצב נתון. כלומר, אני מאמינה שכולנו נולדנו עם קלפים מסוימים שאנחנו יכולים לשחק איתם ואנחנו אלו שבוחרים איך לשחק. עכשיו, לכל אחד חסר משהו, אבל ברגע שאני אחליט שאני משחקת עם מה שיש לי, למרות שאני מרגישה שיכול להיות שאין לי איזשהו קלף מסוים, אני עדיין חושבת שאני יכולה לשחק ולנצח. יהיו כאלה שיוותרו על זה ויגידו 'אוקיי, אני לא רוצה, אני מעדיף לשבת בצד'. זה לדעתי להפסיד את החיים.\""},{"t":"p","x":"**בן דוד בעלת ניסיון אולימפי עשיר. פריז כבר הייתה האולימפיאדה השלישית שלה אחרי ריו וטוקיו.**"},{"t":"p","x":"״בריו לא באמת הבנתי מה קורה, בדיוק יצאתי לשירות לאומי והייתי בתקופה מגוונת״ היא משתפת על האולימפיאדה הראשונה כשהייתה בת 19 בלבד: ״הייתה לי מצד אחד את המסגרת של הנתינה ומצד שני את ההתמסרות לאימונים ולתחרויות״ היא ממשיכה: ״רק כשהגענו לריו, זה הרגע שאת מבינה מול מה את מתמודדת, כשאת קולטת את גודל המעמד. פתאום הבנתי כמה זה מיוחד להיות שם, במקום שכל כך הרבה ספורטאים היו חולמים להיות בו. זה הכניס אותי לפרופורציות והבהיר לי בשביל מה אני נלחמת ומתאמנת כל כך קשה״ ."},{"t":"p","x":"**״טוקיו הייתה קצת שונה״ **ליהיא מספרת שבזכות הניסיון בריו ההכנות לטוקיו היו הרבה יותר מקצועיות וממוקדות. אבל אז פרצה הקורונה והאולימפיאדה נדחתה בשנה ״מה שהפך את המסע למאתגר במיוחד״ היא מפרטת: ״במשך שנה וחצי כמעט לא היו תחרויות, וזה היה קשה לי במיוחד, כי אני שחקנית של תחרויות. מאוד קשה לי רק עם אימונים, אבל התקופה הזו חינכה אותי להבין שאפשר להיות הישגית גם דרך אימונים. הבנתי שאני לא חייבת את האדרנלין של התחרויות כדי להוציא מעצמי את המקסימום״."},{"t":"p","x":"האולימפיאדה עצמה הייתה שונה לגמרי ממה שציפתה. היו המון סימני שאלה. כל יום התחיל בבדיקת קורונה, שהייתה מתפללת שהתוצאה תהיה שלילית: ״התחושה הייתה שהכל תלוי במזל – יכולת להתאמן חמש שנים לרגע הזה, ואז פתאום, בלי קשר ליכולות שלך, חיובית לקורונה והחלום נגמר. זה היה כל כך לא פרופורציונלי״. בגלל הקורונה האווירה בטוקיו הייתה שקטה מאוד, בלי קהל ועם בידוד מוחלט אחד מהשני: ״ואז את מגיעה למגרש – ושם את מרגישה את החוסר. חלק מהאווירה באולימפיאדה, במיוחד בספורט פראלימפי, זה הקהל״. ליהיא מספרת על השינוי בציפיות המקצועיות: ״אם בריו המטרה הייתה פשוט להשתתף, בטוקיו כבר היו ציפיות גבוהות יותר – להגיע לרבע גמר לפחות, ואפילו יותר מזה. עמדנו במטרה של רבע הגמר, אבל לא הצלחנו להתקדם מעבר לזה. הקבוצות האחרות פשוט היו טובות יותר, וזה השאיר תחושה של החמצה מסוימת״. בעקבות הדחייה של טוקיו בשנה, ההפרש לפריז היה רק 3 שנים: ״זה גרם לי לחשוב שזה בהחלט אפשרי, והאמת שזה היה מפתה. ידעתי שהתקופה הקרובה תהיה אינטנסיבית מאוד, אולי אפילו יותר ממה שהיה קודם בגלל שהכל הצטמצם״."},{"t":"p","x":"**בפריז ליהיא נבחרה להיות נושאת הדגל בטקס הפתיחה ביחד עם אדם ברדיצ׳בסקי , **היא משתפת בתחושות: ״האמת היה מרגש, זו חוויה שתלווה אותי כל החיים. בטח עם הקהל הגדול, שחלקו הריעו לישראל. לצערי הרב גם היה קומץ קטן שלא, אבל גם זו הייתה חוויה,  להראות להם שאנחנו פה, אם אתם רוצים או לא ישראל כאן. זה היה מדהים, ממש הרגשה של שליחות״. את ההודעה  על כך שנבחרה היא קיבלה בהפתעה. ההתאחדות ארגנה לליהיא ואדם ריאיון מדומה עם הIPC, הארגון העולמי של הספורט הפראלימפי: ״הדופק שלי עלה לשלוש מאות כי לא הכנתי את עצמי לראיון עם IPC ועוד הראיון באנגלית אז צריך לתרגל את הדברים האלה לפני״  היא מספרת על הרגע שמנכ״ל ההתאחדות מתחיל לדבר: 'אנחנו מכירים את ההישגים הספורטיביים שלכם, ליהיא את מובילה את הנבחרת ואדם שהצליח לשמור על הדרוג העולמי  שלו בטניס, בצל המלחמה , לכן  אין לנו ספק  שאתם ראויים לשאת את הדגל בטקס הפתיחה.'  ההתרגשות הייתה בשיאה, \"בשבילי זו היתה הקלה  כי הבנתי שאין  ראיון באנגלית'. אבל מאז לגמרי צוחקים עליי, וכל פעם שאני פוגשת את החבר'ה של ההתאחדות, אומרים לי 'יש לך ראיון'״."},{"t":"p","x":"**בפריז נבחרת הכדור שער עמדה בציפיות והבטיחה מדליה אחרי ניצחון בחצי הגמר:**"},{"t":"p","x":"\"זה היה מטורף!! זה שילוב של ביטחון, כי ידענו שזה מה שאנחנו יכולות לעשות, לבין תחושת רגש עצומה. זה היה רגע היסטורי – אף נבחרת לאומית בענפי הכדור לא עשתה את זה לפנינו. ההתרגשות הייתה לא רק על הזכייה עצמה, אלא גם על כל הקהל מהארץ שהיה שם ותחושת הליווי המדהימה, גם מהארץ עם כל ההודעות שקיבלנו אחריי התחרות. התחושה שאת לא עושה את זה עבורך  אלא זה משהו גדול יותר מעבר להישג האישי״. **הן נעצרו רק כשהפסידו בגמר האולימפי, והתחושות היו מעורבות, **״הייתה תחושה די קשה באותו רגע, תחושה של אכזבה וכעס, ההרגשה היתה שהגיע לנו יותר. עם זאת, בהיבט השכלי, ניסיתי מאוד לנרמל את ההפסד ולהגיד לעצמי שזה בסדר, יש כאן הישג מאוד משמעותי. להיאחז בו ברמה האישית והלאומית  למרות התחושות הקשות״."},{"t":"p","x":"**אז את חושבת שההפסד בטוקיו גרם לכם לזכות במדליה בפריז? נתן מוטיבציה?**"},{"t":"p","x":"״אני חושבת שההפסד בטוקיו וגם הדרך לשם, חינכו אותנו כקבוצה. אני יכולה להגיד לפחות על עצמי כספורטאית שזה חינך אותי מאוד וצברתי משם ניסיון אדיר. זה לימד אותי להתמודד עם סיטואציות שונות. היו גם לחצים שונים שבכלל לא קשורים לספורט, כמו העובדה שאין תחרויות ואת צריכה להיות עכשיו הכי טובה, בלי קשר למי שמולך - פשוט יותר טובה מעצמך. אז כן, זה תרם לנו בדרך לפריז.״"},{"t":"p","x":"**מה את עושה מבחינה מנטלית לפני משחק?**"},{"t":"p","x":"**״**לפני כל משחק, אני מכינה את עצמי מנטלית בידיעה שאנחנו באות לנצח. זה לא משנה מול מי אנחנו משחקות, אני מגיעה עם תחושת ביטחון שזו התחרות שלנו. אם זו קבוצה שנחשבת חלשה יותר, אני מנסה לעורר בעצמי מוטיבציה ולהראות ביצועים מעולים. אם זו קבוצה חזקה יותר, אני לוקחת את זה כאתגר – זה מה שמושך אותי.״ ליהיא משתפת בכלים חשובים להתמודדות עם לחץ: ״כשאני מרגישה לחץ, אני קודם כל מקבלת אותו. מבחינתי, לחץ הוא אינדיקציה לכך שמשהו חשוב לי. אני מזכירה לעצמי שאם אני פה, זה כי אני ראויה. אם הלחץ גובר, אני מוצאת דרכים להרגיע את עצמי – מוזיקה רגועה, נשימות עמוקות, או פרופורציה על החיים: אני נזכרת שיש דברים הרבה יותר קשים ממה שאני עומדת מולו״."},{"t":"p","x":"**בנוסף להיותה ספורטאית ליהיא גם בעלת שני תארים ממכללת וינגייט,נציגת הספוטאים בוועד הפראולימפי , מרצה על הדרך שלה ומאמנת**. היא מספרת איך היא מספיקה הכל ומנהלת את הזמן:  ״חלק מהדברים שאת לומדת בספורט זה סדר עדיפויות ותעדוף, והשתמשתי בזה גם בלימודים. את יודעת לעשות שיקול וחישוב של ההשלכות ולפי זה לתכנן את הזמן״. **על התשוקה לאמן היא אומרת **, בחרתי לאמן ממקום של תודה, כי ראיתי איזה כלים הספורט נתן לי. האימון בשבילי זה להעביר את זה הלאה, לילדים. בעיקר בשביל להפוך אותם ולתת להם כלים להיות אנשים טובים יותר.״"},{"t":"p","x":"הרצאות היא הגיעה במקרה, אחרי שביקשו ממנה להעביר פעילויות והדברים התגלגלו לזה,  למרות שיש לה פחד קהל! כששאלתי אותה איך היא מתמודדת עם זה זה היא ענתה: ״פשוט עולה לבמה . אבל שוב, יש לי איזו שריטה - אני מתה על זה. אני אוהבת להרגיש פחד, אני אוהבת להרגיש את הקצה, זה אחד הדברים שאולי מבדיל שחקנית של תחרויות ולא רק שחקנית של אימונים. חובת ההוכחה היא עלי, להתמודד מול הדבר הזה, אז זה כיף.\" מדהים."},{"t":"p","x":"כשבן דוד נשאלת על החשיפה של הספורט הישראלי היא מודה כי \"השיווק הוא לא התחום החזק של הספורט האולימפי והפראלימפי\" וממשיכה להסביר איפה זה פוגש אותה כספורטאית \"אנשים יוצאים לתחרויות, נותנים את הגוף  ואת הנשמה שלהם ושמים את המטרות וההישגים שלהם לפני הכל, אבל עדיין - רוב הציבור בכלל לא מודע לזה\". היא מזכירה שמות שנחקקו לנו בתודעה אחרי האולימפיאדה, כמו תום ראובני או שרון קנטור \"קשה לי להאמין שאנשים ידעו מי הם לפני פריז, או ידעו מי זה ארטיום לפני טוקיו\" ולצערנו, זה נכון. הטראומות שאנחנו עוברים במדינה מאז ה-7 באוקטובר, להרגשתה, שפך קצת יותר אור על הספורט וההישגים, אבל בן דוד אומרת בצדק, \"זה לגמרי משהו שאפשר למנף גם בלי לחכות לטרגדיות או לתירוצים מיוחדים. הספורט האולימפי והפראלימפי הוא נכס לאומי בפני עצמו, והוא ראוי ליותר הכרה ותמיכה שוטפת.\""},{"t":"p","x":"לליהיא יש חזון ברור, שממש לא קשור רק בספורט \"שאנחנו נצליח להיות חברה אחת. ברגע שנבין שאין פה מישהו שיותר טוב מהשני\". הרצון שלה שנהפוך לחברה שוויונית שרואה ומכילה את כל החלקים השונים שבה הוא לא משהו ששמור לעיתות מלחמה, אלא משהו שהיא חיה יום יום \"זה שאני עשיתי מדליה אולימפית, זה לא אומר שאני טובה יותר ממישהו שלא עשה את זה\" היא מסבירה, \"או מישהו שהצליח עם חברת ההיי-טק שלו ומכר אותה במליארדים, הוא לא יותר טוב ממני\". לטענתה זאת ההבנה שאנחנו חברה אחת, מקשה אחת \"כל אחד ואחת טוב או טובה בתחומה ופחות בתחומים אחרים - זאת השלמות. התחרות לא צריכה להיות אחד נגד השני, אלא בשיתופי פעולה. אם נבין את זה, נגיע להישגים הרבה יותר גבוהים.\""},{"t":"p","x":"**לפני סיום, שאלתי את ליהיא, איזה טיפים היית נותנת לבנות צעירות המתמודדות עם אתגרים?**"},{"t":"p","x":"\"קודם כל ליהנות מהדרך ! גם כשיש קשיים, לחבק אותם בשתי ידיים ולהגיד 'אני אחרי זה הולכת לצאת הרבה יותר חזקה, הרבה יותר גדולה'. ככה אפשר ליהנות מהקושי, כמה שזה נשמע מוזר, אבל ליהנות מכל החספוסים האלה שעוברים בדרך. בסוף, הכל עובר, המציאות קורית אז צריך ליהנות ממנה ולדחוף הכי גבוה שיש, בלי לפחד ליפול בדרך, כי הנפילות זה מה שבונה אותנו.\""}]},"כדורסל-נשים-כחול-לבן-צריך-לעשות-מזה-עניין":{"b":[{"t":"p","x":"ביום חמישי, 16 בינואר, התקיים כנס של WSP בשיתוף מנהלת ליגת הכדורסל. בכתבה שהתפרסמה מיד לאחריו הבאנו את הקולות שנשמעו על במת הטקס והיום אנחנו מביאות לכן את הקולות של השחקניות. בשנים האחרונות כדורסל הנשים בעולם בפריחה ובכלל, ספורט נשים על ענפיו השונים זוכה סופסוף לבמה הראויה לו. אז למה אצלנו, זה עוד לא קורה? מה אנחנו צריכות לעשות כדי לעלות על הגל?"},{"t":"p","x":"במהלך הכנס שאלנו שחקניות שלוש שאלות כדי לנסות להבין קצת יותר איך יוצרים שינוי מבחינתן:"},{"t":"p","x":"**מה הופך את כדורסל הנשים הישראלי למוצר מנצח?**"},{"t":"p","x":"הבנו, שבעיני הכדורסלנית הישראלית, הענף שלה הוא מוצר מנצח - זה ברור. הן מביאות משהו אחר למגרש, משהו שאי אפשר למצוא בשום מקום אחר. \"זאת ההנאה, שאנחנו עושות מהלב, מקריבות\" משתפת ירדן דנן \"זה משהו ששווה לראות\". עדן רוטברג מוסיפה \"אני חושבת שאנשים לא מודעים לזה שבכדורסל נשים יש שחקניות באמת באמת טובות שמשקיעות המון  מהזמן שלהן, זאת העבודה שלנו פול טיים ג'וב\" היא מנסה להסביר את הפערים בין התפיסה של הענף בחברה הישאלית לבין מה שהוא בפועל עבור השחקניות. \"אני חושבת שאנחנו באמת טובות, הרבה זמן לא היו בנות מוכשרות כאלה.\" כשעדן מדברת על הדור הצעיר יש לה ניצוץ בעיניים והיא באמת מאמינה שגדל פה דור מיוחד של שחקניות שכמוהו עוד לא היה. ברמה המקצועית, לטענת תמר ברגל \"כמו שהמשחק התפתח בארצות הברית, לנשים יש יכולת קליעה מעולה, אפשר לראות את זה במיוחד אצל הישראליות\". ברגל מתייחסת כמובן לתופעת קייטלין קלארק האמריקאית שיש אומרים ששינתה את כדורסל הנשים, מה שבטוח, זה שהיא יצרה סביבו באז שכמוהו עוד לא היה. מי שהעלתה נקודה מעניינת למחשבה בנושא הייתה צליל וטורי, לטענתה, \"ראינו את זה גם בקורונה אנשים נהנו לראות את השחקניות הישראליות יש וייב אחר יש אווירה כיפית על המגרש אני חושבת שיותר צופים נהנים לראות את הכדורסל הזה, זה הרבה יותר חכם, יש טקטיקה יש תרגילים\". יכול להיות שזה חלק מהסיפור? החיבור של הקהל עם השחקניות ועם הווייבים? או אולי הרצון של הצופים לראות משחק קצת יותר מתוחכם וטקטי?"},{"t":"p","x":"**מה צריך לקרות כדי שנראה את היציאים מלאים בקהל כמו שקורה ב-WNBA או בליגת המכללות האמריקאית?**"},{"t":"p","x":"נושא החשיפה הוא נושא רגיש אצל הכדורסלנית הישראלית, בין אם בצדק ובין אם לא, השורה התחתונה היא שהחשיפה כמעט ולא קיימת. בארה\"ב, השחקניות פעלו בכמה מישורים במקביל על מנת לשנות את זה: המישור הראשון היה על המגרש כאשר אהבתן למשחק הפכה לאובססיה שהביאה את הענף לרמות משחק חדשות. המישור השני היה חשיפה עצמית מאסיבית דרך הרשתות ואמירה ברורה: אם אתם לא רוצים להראות אותנו, אנחנו נראה את עצמנו ונראה לעולם מה אנחנו שוות. המישור השלישי היה המשך המאבק רב השנים שלהן (שנמשך עוד היום) לקבלת הכרה וזכויות שוות לאלו של המקבילים הגברים."},{"t":"p","x":"אז נכון, הן עדיין לא מקבלות את אותן סכומים שמקבלים שחקני ה-NBA, גם לא את אותם אחוזים של הכנסות (על זה הן נאבקות בעצם), אבל הן מקבלות את אהדת ואהבת הקהל, את החשיפה ואת חוזי הפירסום שמאפשרים להן להתפרנס בכבוד מהמשחק שאותו הן כל כך אוהבות."},{"t":"p","x":"ומה חושבות הישראליות? להן זה ברור שהחיבור לקהל ולקהילה הוא מה שישנה עבורן את המשחק. לצליל וטורי זה ברור \"כדורסל כחול לבן זה כדורסל יפה שאנשים אוהבים לראות. כשיש הרבה זרות הצופים לא מרגישים שייכות למשחק הזה, אנשים אוהבים לראות ישראליות\". וירדן דנן מסבירה \"קודם כל, לחבר בין הקבוצה לקהילות. כל אחת בעיר שלה, לעשות פעילויות, ללכת לבתי ספר, פרסומים בעיר, שלטים, קצת להעלות מודעות.\" היא מודה שהיו זמנים שזה היה אחרת, \"הייתי הולכת ברמלה והיו מזהים אותי, כי היו שלטים בעיר, בכבישים הראשיים, בבתי ספר, אם אין שום שלט איך אנשים ידעו שיש משחק?\". השחקניות מסכימות שזה עניין של תרבות. תמר ברגל מסבירה גם היא את שורש הבעיה התרבותית מהעיניים שלה, \"זאת תרבות ספורט כוללת. גם אם נעלה את מספר האנשים שרואים כדורגל נשים או כל ספורט נשים אחר, זה לא משנה, המצב הוא גורף\" היא אומרת בצער ומסבירה \"בבית ספר,שיעור ספורט, נותנים כדור, תשחקו מחניים, תעשו מה שבא לכם. כל הילדים בטלפון, במקום לגרום לאנשים לרצות לזוז ולהיות בחוץ\".  עדן רוטברג ממשיכה את אותו הקו מנקודת המבט שלה \"הייתי ביורוקאפ, בליגה האירופאית ובכלל באירופה, זה פיצוץ אוכלוסין שזה כיף לשחק!\" היא אומרת ומבינה ש\"זה תהליך וגם עניין של תרבות. תרבות הספורט בארץ לוקה, לא רק (ספורט) נשים, גם גברים\" היא קובעת. \"אני כן רואה איזו שהיא התקדמות\" היא מודה, \"אני חושבת שגם מהצד שלנו, אנחנו צריכות לשתף המון, לבוא לבתי ספר, לבוא לקהילה, לשתף באינסטגרם, בטיקטוק, בסוף זה מה שמוכר.\""},{"t":"p","x":"**מה את, כשחקנית, עושה כדי לשנות את פני הענף והעתיד שלו?**"},{"t":"p","x":"בסופו של דבר, השינוי בספורט מגיע פעם אחרי פעם מהספורטאיות עצמן ונראה שגם הכדורסלניות כחול לבן מבינות את זה. הדר חדד למשל, משתפת \"יש לי טיקטוק, שהוא נותן ים של צפיות, מאות אלפים ואני מדברת על הכדורסל, על חיי היום יום שלי. זה יוצר חשיפה, הרבה בנות צעירות מזהות אותי בעקבות זה\". צליל וטורי מספרת על החוויה שלה ברמלה והחיבור לקהילה \" כקבוצה אנחנו הולכות הרבה לבתי ספר\". אבל היא לא מסתפקת רק בזה, \"גם אישית, אני משתפת באינסטגרם, אני גם מאמנת אז אני מדברת על כדורסל נשים\". תמר ברגל מצידה אומרת \"כל מקום שאני מגיעה אליו אומרת שאני שחקנית\" ומודה שזה מעורר תמיד שיח, אנשים מתעניינים, שואלים שאלות והיא תמיד אוהבת לענות ולהסביר."},{"t":"p","x":"מבחינת עדן רוטברג זה לגמרי חלק מהדיל \"יש לי אינסטגרם, אני משתפת המון. כל פעם שמתייגים אותי אני משתפת.\" היא מסבירה, \"אני משתפת מחיי היום יום שלי, הייתי שמחה אם היה לנו קורס לתקשורת ספציפי לכדורסל, לשחקניות המובילות\" רוטברג מסבירה ומסיימת \"כמו שאמרתי, זה דו צדדי זה צריך להיות גם מהצד שלנו וגם מהצד של ההנהלה\"."}]},"הסוד-של-רז-שיחה-עם-רז-הרשקו-לא-רק-על-ג-ודו":{"b":[{"t":"p","x":"**רז ואני נפגשות בשישי בבוקר בבית קפה ליד מכון וינגייט. עד שהגעתי היא כבר הספיקה להתיידד עם המלצר ולקבל את פניי בשמחה. בשיחתנו רז מספרת לי על כלל הברזל שנקבע עוד לפני שנולדה, איך הרגישה בשניות אחרי הגמר באולימפיאדת פריז ועל תקופת השבר שלה בקריירת הגודו.**"},{"t":"p","x":"**הרשקו, שרק בקיץ האחרון זכתה במדליית הכסף באולימפיאדת פריז, כבר סימנה לעצמה את היעד הבא והחלה במסע שלה לעבר אולימפיאדת לוס אנג'לס 2028. \"**סיימתי את המשחקים האולימפיים עם מדליה ואז כבר חשבתי קדימה, הרגשתי בפנים שיש לי עוד מה לתת. יש בי את האש הזאת ובא לי להראות לעצמי שאני יכולה יותר, אז אמרתי יאללה, אני ממשיכה.\" **הרשקו משתפת ומוסיפה **״מבחינתי, כל יום הוא יום חדש ואני לא יודעת מה הולך להיות, חוץ מזה שאני רוצה להיות יותר טובה ממה שהייתי אתמול.\""},{"t":"p","x":"**הוריה של הרשקו שלחו אותה לחוג ג'ודו בגיל 4 ובגיל 14 היא החליטה להפוך את הגודו ליותר מתחביב, **״אהבתי את הסביבה, את זה שאני יכולה להיות מי שאני, את זה שכל אחד יכול להיות שונה ולא מנסים להפוך אותך למשהו שאתה לא. אהבתי שזה תלוי בי, בסופו של דבר אני על המזרן לבד. הכרתי שם חברים שהם כמו משפחה שלי\".** הרשקו התבלטה בכישרונה מגיל צעיר וקטפה את המקומות הראשונים בתחרויות בארץ ובחול.** \"כשהייתי יותר צעירה לא אהבתי לעבוד קשה הייתי בכיינית, וותרנית והיה את הכישרון הזה, אבל כמו שאומרים, עם כישרון לא הולכים למכולת צריך גם לעבוד קשה\"."},{"t":"p","x":"**אחרי מדליית הכסף בפריז, אליפות העולם וההישגים הרבים שכבר השגת, מה את מרגישה שמניע אותך להמשיך במסע שלך על המזרן כרגע? **"},{"t":"p","x":"״ספורט הישגי נמדד לפי מדליות ומבחינת המאמן לפעמים הדרך לא חשובה, התוצאה חשובה. אני פה להגיד 'נכון, מדליות זה חשוב, אבל אם אני לא אוהבת ולא נהנית ממה שאני עושה כלום לא יצליח ולא יביא לי הישגים. זה כמו הביצה והתרנגולת, אם אני נהנית ואוהבת את הדרך ומצליחה להפיק מהדרך דברים שאני רוצה, יכול להיות שאני לא אזכה במדליות, אבל אני יודעת שנתתי את כל כולי במשהו שאני רוצה לעשות ואוהבת.\""},{"t":"p","x":"**כשזכית במדליה כל מדינת ישראל הרגישה גאווה, את גם הרגשת את הגאווה הזאת?**"},{"t":"p","x":"״חד משמעית. מאז ומתמיד הייתי גאה להתחרות בכל מקום בעולם בתור ישראלית-יהודייה, לייצג את כל עם ישראל ואת כל היהודים בעולם. אחרי ה7.10 נהיה לי אקסטרה בוסט לכל מה שאני עושה, מעבר לחלום שלי האישי זה הפך להיות חלום לאומי. כל מה שאני עושה זה בשביל כולם, המדליה הזאת היא לא רק שלי היא של כולנו. אני באמת הרגשתי את זה באולימפיאדה בלב ובראש. הגיעו המון אנשים מישראל ויהודים מהעולם, הרגשתי שאני מתחרה בתל אביב, זה  נתן את הדחיפה הזאת בגב כשצריך״."},{"t":"p","x":"**מה היו התחושות שלך אחרי ההפסד בקרב על מדליית הזהב?**"},{"t":"p","x":"״מבאס לסיים את היום בהפסד. איך שהפסדתי התחלתי לבכות, הרגשתי שיכלתי לזכות בזהב. אני מאוד מנסה כשיש משהו שלילי להפוך אותו לחיובי באותה שנייה, משהו שאני עובדת עליו המון זמן וזה תהליך שלא יגמר לעולם.\" **רז משתפת בפתיחות רבה וכנות שכל כך אופנייניות לה** \"יש לי נפילות לפעמים. הפסדים שאני אומרת ואוו איזה גרועה אני, מה אני עושה. אני נותנת לעצמי רגע לפרוק עול ואני מחברת את עצמי מחדש ישר אחר כך.\""},{"t":"p","x":"**הרשקו עובדת עם פסיכולוג ספורט ומשתמשת בטכניקות מנטליות ביניהן דיבור עצמי חיובי ורוטינה קבועה לפני ביצוע. **יש לי רוטינה מסוימת הכל ממוספר, יש לי אותו מספר של מתיחות, סיבובי ידיים כאפות לידיים, כאפות לפנים, מספר קפיצות, סיבובי אגן, הכל אותו מספר, כל פעם אני עושה אותו הדבר.״ **רז מסבירה לפרטי פרטים: **״יש לי רוטינה של דיבור שאותה אני לא אומרת אבל היא איתי כבר עשר שנים, ברגע שהדופק עולה והלחץ עולה אני חוזרת על זה. זה משפט שמחולק לשלושה חלקים ואני מדברת את זה עם פה פתוח כמו ממלמלת וחושבים שאני משוגעת לגמרי.״"},{"t":"p","x":"**איך זה מרגיש שמזהים אותך ברחוב? ניגשים? מבקשים תמונה? **"},{"t":"p","x":"״כן מבקשים. זה מרגש, זה מביך, אני מוחמאת. זה משמח לשמוע שמשהו שאני עשיתי, שמגיל קטן חשבתי וחלמתי עליו, היה רק שלי ועכשיו הוא של כולם, זה מרגש את הלב.\" **הרשקו מציינת שהיא עונה לכל הודעה שנשלחת אליה באינסטגרם** \"זה חשוב לי, זה לא סתם עוד וי בדרך. הם עושים את כל המאמץ וצופים ושולחים הודעה ומתעניינים, אז אני מחזירה כמה שאני יכולה לתת מעצמי לאחר. מבחינתי זאת המתנה הכי גדולה שאלוהים יכול להעניק למישהו, אז אם מישהו מרגיש בנוח להתייעץ איתי, אני שמחה ואני מנסה לעזור כמה שאפשר.\""},{"t":"p","x":"**אם היה שיעור בבית ספר על איך לבנות מנטליות חזקה, כנראה שרז הרשקו הייתה זאת שמעבירה אותו. ״בשנייה שעשיתי את הסוויץ הזה בראש והפכתי כל \"חיסרון\" ליתרון הכי גדול שלי, אני חושבת ששם זה התחיל לעבוד לי.״ רז מספרת.  ואכן, רז למדה איך להעזר בכוח העצום שיש לה בתוך הראש ולתרגם אותו לכוח הפיזי שהיא מציגה על המזרן. **״ב 2018-2019 עליתי מקטגורית משקל של עד 78 לקטגוריה של 78 פלוס, משהו שהיה זר וחדש לי. במשך שנה וחצי בעצם הפסדתי בקרב הראשון בכל תחרות וכל פעם מחדש את מנסה להיות חיובית. באיזשהו שלב את טסה ושואלת את עצמך: למה אני טסה? לא בא לי. לא בחרתי בזה בשביל להיות הכי גרועה בעולם, רציתי להיות הכי טובה בעולם.\""},{"t":"p","x":"**בתקופה הקשה הזאת בקריירה של הרשקו היא נעזרה בצוות ובמאמנים שלה אבל בסוף, הבינה שזה צריך לבוא ממנה  **״זה היה צריך לבוא ממני עם השלמה עצמית שאת כל החסרונות שאני חושבת שיש לי אני צריכה להפוך ליתרונות. בשנייה שעשיתי את הסוויץ הזה בראש וכל חסרון הפך ליתרון, הכל התחיל לעבוד.\""},{"t":"p","x":"**שני הרשקו מאמן נבחרת ישראל נשים בג'ודו הוא גם דודה של רז, היא מספרת על הקשר החזק ביניהם **\"מאז שהתחלתי ג׳ודו הוא לא זכור לי בראש כדוד.\"  **היא מודה** \"אני חושבת שמערכת יחסים בין מאמן למתאמנת זה קשר שהוא מאוד חשוב כי בסופו של דבר הוא זה שנותן את הפידבק, הוא איתי יותר מכל אחד אחר. אני על המזרן לבד והיחיד שנמצא שם זה המאמן וכמו שאני צריכה לסמוך עליו, הוא צריך לסמוך עליי.\""},{"t":"p","x":"**כשהיית צעירה יותר היו מצבים שבהם ההורים שלך חשבו משהו אחד ושני (המאמן) חשב משהו אחר?**"},{"t":"p","x":"**\"**כשיש ארוחות משפחתיות גדולות יותר ואירועים משפחתיים יש  חוק ברזל עוד מלפני שנולדתי- לא מדברים על ג׳ודו.\" **הרשקו משתפת שלפעמים בספורט הישגי הילד מתקשה ולהוריה היה קשה לראות אותה ככה** \"ברור שלפעמים הם חשבו א' ושני חשב ב', אבל הם היו מעורבים אך לא מתערבים. הם היו שם בשביל לתת לי את הגב והתמיכה שאני צריכה בשביל שאני אוכל לעשות ולנסות להיות הכי טובה במה שאני רוצה.\""},{"t":"p","x":"**מה את חושבת שאפשר לעשות כדי לעודד ילדות ונערות לעסוק בספורט בישראל ובג'ודו בפרט?**"},{"t":"p","x":"״משנה לשנה רואים את הגדילה, ההתפתחות והצמיחה של הענף הזה וזה פשוט מחמם את הלב. כשאני הייתי יותר צעירה זה היה נחשב לספורט גברי. הייתי בת יחידה בחוג ועכשיו יש המון מקומות בארץ שיש לך שיעורים רק לבנות!\"**הרשקו מספרת בשמחה וגאווה רבה \"**יש פה מגמה שהיא מתהפכת וזה בכל העולם, אבל תמיד יהיו אנשים שיגידו: אהה זה ספורט גברי יא אבו גבר\" **קראו לך אבו גבר? **״כן. בבית ספר, ילדים בשכבה. היה קל לרדת עליי, הייתי קצת שמנמנה, עם משקפיים, שביל באמצע, התלבשתי כמו טומבוי, עשיתי ג׳ודו, שיחקתי כדורגל בהפסקות\" **הרשקו צוחקת ושואלת מה עוד צריך לספר?** \"היום מרגיש לי שיש שיח יותר פתוח ומגמה מטורפת, ברור שזה לא מושלם ותמיד יש מה להשתפר.\""},{"t":"p","x":"**הרשקו מוסיפה שהרבה הורים לבנות פונים אליה ומספרים שהן מתקשות להיות הבנות היחידות בחוג **\"הדבר היחיד שיש לי להגיד להם זה: אם הן אוהבות את זה, שום דבר לא רלוונטי ולא מעניין. שימישיכו להיות מי שהן וזה חשוב גם בתור הורים לבוא ולתת את המקום הזה לילדים\". **היא ממשיכה ומסבירה שלהורים שלה יש השפעה רבה על האישה החזקה שהיא היום **\"מאז שאני זוכרת את עצמי ההורים שלי אמרו לי: 'רז, תהיי מי שאת, עם הלב שלך, את הכי מיוחדת אין עוד אחת כמוך' וזה מה שהלך איתי כל הדרך.\" **גם כאשר היה צריך לדבר עם הבית ספר הם היו מאחוריה** \"יש לך חלום? את יכולה להגשים אותו. בית ספר אפשר להשלים אחר כך, חלומות אי אפשר להשלים אחר כך. הם היו שם בשבילי כגב כתומך.\""},{"t":"p","x":"**במה את הכי גאה במסלול שלך עד היום?**"},{"t":"p","x":"״אני הכי גאה שלמרות הכל דרך כל הקשיים, הכשילנות והאכזבות וגם הרגעים השמחים שכל פעם מחדש אני המשכתי ואני עדיין ממשיכה להישאר ולהיות מי שאני ולא להקשיב לרעשי רקע.\" **הרשקו לא קוראת את הטוקבקים** ״זה לא רלוונטי. זה לבוא להסתכל לעצמי רגע בתוך הלב ולהגיד 'רז, מה את רוצה? מה את אוהבת? איך את?' ולהמשיך ולדעת לאהוב את מי שאני, לקבל את מי שאני, זה תהליך.\" הרשקו מודה שזה לא קל, \"אני מדברת על זה עכשיו בצורה כזאת בוגרת אבל זה עדיין תהליך. יש ימים שאני קמה ואני מבואסת על עצמי. זאת עבודה קשה, כל יום. גם אם כל יום מחדש יש משהו אחד קטן לשפר, אני אשפר. אני גאה שלמרות הכל ובזכות הכל אני ממשיכה להקשיב לעצמי.״"},{"t":"p","x":"**חברות של רז לנבחרת מעידות עליה שהיא הבן אדם הכי נגיש בנבחרת, מתחברת ועוזרת לכולם מהקדטיות עד לבוגרות.**"},{"t":"p","x":"**אני שואלת את רז איך היא הייתה מספרת על עצמה לקהל בבית בלי להזכיר את הג'ודו, רז מתפתלת על הכיסא באי נוחות ומתקשה להעיד על עצמה.  **״מי אני? אני לא יכולה לדבר על עצמי ככה. אני לא אוהבת להרים לעצמי\"."},{"t":"p","x":"**אני צוחקת ואומרת לה שזה יישאר בינינו, למרות שלשתינו ברור שמתבשלת פה כתבה והיא נפתחת קצת, **\"אני מצחיקה, אני יודעת לבשל, אני אוהבת לקרוא ספרים.\"** היא מתחילה לשתף **\"הארי פוטר, מתה על זה. יש ספרים של דרמה, רומנטיקה.״**רז ממשיכה, **\"יש המון טיסות, המון זמן מת במטוסים זה מה שעושים, אני קוראת ספר, לומדת.\"\"התחלתי תואר ראשון בהוראה וחינוך גופני. לפעמים קשה לשלב.\" **ובלי לשים לב היא חוזרת למזרן.. **\"אני חושבת שאני מאוד מגוונת בג׳ודו שלי, מתפרצת.\" אני עוצרת אותה, **אבל רז, אמרנו בלי לדבר על ג׳ודו! **״אה נכון, בחיים אני חושבת שאני יודעת להיות נאמנה, אני לא יכולה להעיד על עצמי שאני יכולה להיות חברה טובה.אני מרגישה שאני מאוד אכפתית לסביבה ולזולת, מנסה תמיד לתת כמה שאני יכולה מעצמי לאחרים. זה ממלא אותי שאני עוזרת למישהו.״"},{"t":"p","x":"**מה היית אומרת לרז הרשקו הילדה מהמקום שאת נמצאת בו היום?**"},{"t":"p","x":"תמשיכי להיות מי שאת, לכי עם הלב שלך, לכי אחרי החלום שלך, תעשי רק מה שאת רוצה, רק מה שעושה אותך מאושרת, אל תקשיבי לאחרים בחוץ, זה לא רלוונטי. תמשיכי בדרך שלך.״  **רז מדגישה ומחדדת \"**זה הרבה עבודה עם עצמי גם כל פעם את מנסה לשנות משהו ואז את מבינה עם עצמך: 'אוקיי זה בסוף חוזר אליי, זה הרצון שלי, החלום שלי, מה שאני רוצה זה נבנה על זה.' אני הולכת לישון עם עצמי וקמה עם עצמי בבוקר.\" **את רצית באיזשהו שלב להתשנות?**"},{"t":"p","x":"\"לא. אבל את יודעת, יש המון לחץ מהסביבה שאת צריכה לעשות ב' ולא א' ואת רוצה כל כך אלף.\" **הרשקו מודה שזה לא קל להחליש את רעשי הרקעולהקשיב לעצמך תמיד** \"מישהי רוצה ללכת לעשות חוג מקרמה ואומרים לה 'לא, את לא יכולה, זה לא מביא כסף'. תמשיכו עם מה שאתן רוצות עם מה שאתן אוהבות, אתן חיות עם עצמכן בסוף.\" **אני מחליטה להקשות קצת:אבל רז, בסופו של דבר מי ישלם את החשבונות? **״אפשר למצוא דרכים, מוצאים תוך כדי. אין מה לעשות, הגשמה עצמית זאת התוצאה הכי טובה שאפשר לקבל. **אין עוד אחת כמונו בעולם, כל אחת היא מיוחדת, לא משנה איפה תחפשי, לא תמצאי מתחת לשום אבן מישהי שהיא כמוך או מישהי שהיא כמוני. לא תמצאי.\"  היא קובעת ומוסיפה \"לכו עם האמת, עם הלב, הרצון ועם החלום, עופו על זה.\"**"}]},"לא-עוד-שקט-במגרש":{"b":[{"t":"p","x":"המהפכה של ספורט הנשים יוצאת לדרך, כך הכריז מיזם WSP בכנס שערך אתמול (חמישי) בשיתוף מנהלת ליגת הכדורסל. \"אנחנו דור של שוויון, ואנחנו דורשות את הכבוד האמיתי,\" הכריזה נועה זליבנסקי, שחקנית ליגת העל ומייסדת מיזם WSP, בפתיחת הכנס. \"אנחנו דור שרוצה להפוך את העולם לטוב יותר, דור שרוצה להעצים את תחושת המשמעות שלנו.\""},{"t":"p","x":"המיזם החדש לקידום ספורט נשים בישראל, WSP, מביא קול חדש ורענן לזירה. מקימת המיזם היא, כאמור, נועה זליבנסקי, שחקנית ליגת העל בכדורסל, אשר עומדת בראש צוות של 24 אנשי מקצוע ואנשי שטח מעולמות הספורט השונים בארץ. מטרתו - להעניק במה, לחשוף ולהשמיע את קולן של ספורטאיות ישראל, דרך פודקאסטים, ראיונות אישיים, כתבות שטח ועוד."},{"t":"p","x":"יעל ינקו, אחת מכתבות השטח של  WSP שיתפה בעצמה סיפור שיכול להמחיש יותר מכל דבר אחר את מצבו של ספורט הנשים הישראלי, וכדורסל הנשים בפרט. \"לפני שנתיים החלטתי באופן אקראי להתחיל לצפות בכדורסל נשים. היה אולם ליד הבית, והחלטנו, אני וחברים, ללכת. מאז התאהבתי בליגה. וזה יכול לקרות לכל אחת ואחד.\" סיפורה ממחיש את הפוטנציאל הטמון בחשיפת הענף לקהלים חדשים, השאלה היא איך עושים את זה?"},{"t":"p","x":"**ההנהלה הבכירה מתחייבת למהפכה**"},{"t":"p","x":"הכנס זכה לנוכחות מרשימה של בכירי ענף הספורט: עמוס פרישמן, יו\"ר איגוד הכדורסל, דנה סנדר, יו\"ר מנהלת הליגה, ועופרי יקיר, מנכ\"לית אתנה."},{"t":"p","x":"פרישמן, שהביע אכזבה מהנוכחות הדלה של שחקניות בכנס, הציג חזון ברור: \"אני לא קונה את זה שאנחנו לא מצליחים למלא את האולמות בגלל הפרסום בלבד. יש פה הרבה פוטנציאל ברור, ואנחנו חייבים להרכיב את הפאזל מחתיכות שונות, שכל אחת מהנוכחות פה היא חלק ממנו.\" הוא המשיך והדגיש את הצורך בפעילות בשטח: \"צריך ללכת לרשויות בהן אין כדורסל נשים ולהכניס את זה שם.\" הוא פנה אל השחקניות ואמר \"גם אחרי הפרישה, אתן צריכות להתגייס כמנהלות מחלקה, כמגלות כישרונות וכמאמנות. אחרת כלום לא ישתנה.\""},{"t":"p","x":"דנה סנדר העלתה נקודה קריטית על הפער בין השיווק למציאות: \"עם כל הכבוד למאמצים בחשיפה, אם לא מכירים את השחקניות באופן אישי, אנחנו מפספסים.\" היא קראה לשחקניות לקחת חלק פעיל: \"אנחנו מתחננים שתניעו את הבנות ברשתות חברתיות. שתפו, תעדכנו, נעשה דברים יחד.\""},{"t":"p","x":"עופרי יקיר הדגישה את חשיבות הרגע: \"יש פה הזדמנות היסטורית עם יושב ראש שמאוד תומך, לא רק בדיבורים אלא במעשים.\" היא התייחסה לפער הדיגיטלי: \"אם אני עושה פודקאסט ורוצה לחשוף עוד שחקניות, אנחנו מגלים שבכלל או שאין להן אינסטגרם או שיש להן מספר עוקבים מועט. יש לזה משמעות וחשיבות רבה.\" ועדיין, נראה ששחקניות רבות מעדיפות שלא לקחת חלק ולהתגייס למאמץ המשותף."},{"t":"p","x":"** קריאה נוקבת לשינוי**"},{"t":"p","x":"לירון כהן סיכמה את הדיון בנאום נוקב שהדהד באולם: \"נורא קל לשבת על הגדר ולהתלונן כלפי כל העולם, אבל בואו נצא מזה. בזמני, כדורסל היה מקצוע פר-אקסלנס - אי אפשר היה לשלב את זה עם עוד עבודה. שמתי את כל כולי אך ורק בכדורסל, אכלתי, ישנתי ועשיתי כל דבר חשוב כדי שאני אהיה טובה יותר.\""},{"t":"p","x":"כהן העבירה מסר חד וברור לשחקניות: \"תפקידכן להיות טובות. אם תהיו טובות וכשתהיו טובות - יבואו לראות אתכן, ירצו בכן ויעריצו אתכן. האחריות שלכן היא להסתכל במראה ולשאול את עצמכן - מה אני באמת עושה בשביל להיות השחקנית הכי טובה שאני יכולה להיות? בלי לספר סיפורים לעצמכן.\""},{"t":"p","x":"לצד זאת, כהן הציעה את עזרתה בקידום דרישות מקצועיות: \"אני בכובע שלי היום כיו\"ר הוועדה המקצועית נשים מוכנה להיות הקול שלכן. לא ממקום של התבכיינות, אלא ממקום שאומר - אנחנו רוצות להיות מקצועיות, אנחנו רוצות לעשות הכל כדי להיות ברמה הכי גבוה. במקום הזה, הכוח כן נמצא אצלכן.\""},{"t":"p","x":"הכנס הסתיים בתחושה ברורה - השינוי בספורט הנשים בישראל כבר כאן, והוא מתחיל מהשטח. עם תמיכה של ההנהלה הבכירה, מחויבות השחקניות, וקול ברור וצלול, נראה שהמהפכה בספורט הנשים הישראלי אולי קרובה יותר ממה שנדמה ומה שבטוח, זה שאם כולן תתגייסנה למען המטרה - השמיים הם הגבול."}]},"שיווק-וספורט-נשים-ביצה-או-תרנגולת":{"b":[{"t":"p","x":"שיווק ספורט נשים הוא נושא רגיש. יש שיטענו שהתחום לא משווק מספיק, יש שיגידו שהוא פשוט לא משווק נכון, ויש את אלו שטוענים כי זה פשוט לא ניתן לשיווק מפאת חוסר עניין. הטענה האחרונה הוכחה כשגויה בשנים האחרונות כאשר ספורט הנשים בעולם שובר שיאי צפיה משנה לשנה, כאשר ארה\"ב מסתמנת כמובילת הטרנד. אז למה ההייפ העולמי לא תפס בכחול לבן עדיין ומה צריך לעשות על מנת שהוא יפרוץ? כדי לענות על השאלות האלה ננסה להבין קודם מה השתנה בעולם והאם השיווק הוא הביצה או התרנגולת, ובכלל, מי באה קודם?"},{"t":"p","x":"עובדתית שיווק ספורט הנשים בעולם התפתח באופן משמעותי במהלך השנים האחרונות, וממלא תפקיד מכריע בהגברת הפופולריות והנראות שלו. אבל איך זה קרה? מה השתנה באסטרטגיות השיווק שתרם לעלייה בפופולריות של ספורט נשים והאם נוכל להעתיק את המודל הזה גם לזירה המקומית?"},{"t":"p","x":"בפרק #41 בפודקאסט שלנו אירחה נועה את ד\"ר יעל פודקמיין - מומחית לפרסום, שטענה כי \"יש פער בין השתתפות של ילדות בספורט לבין איך ספורט הנשים הופך (או לא הופך) להיות מותג\". לדעתה \"ספורט הנשים לא נבנה כמותג חזק בישראל, אבל את הפער הזה ניתן לסגור.\" השאלה היא איך. כדי לענות על השאלה ננסה להבין מה קרה ברמה השיווקית בזירה העולמית."},{"t":"p","x":"הדבר הראשון שקרה היה סיקור מדיה מוגבר שנוצר בעקבות נוכחותן של הספורטאיות במדיות החברתיות. ספורטאיות מובילות (לא רק) לקחו את נושא השיווק לידיים שלהן והחלו למצב את עצמן כמותג אישי בפלטפורמות כמו אינסטגרם, טוויטר, פיסבוק ועוד. פתאום, לראשונה, הן כבר לא תלויות בגורם חיצוני והשליטה על הדרך בה הן תוצגנה היא שלהן ושלהן בלבד. המהלך הזה הוביל ליכולת שלהן לתקשר ישירות עם הקהל שלהן, לשתף את הסיפורים שלהן ולהרחיב את מעגל העוקבים שלהן."},{"t":"p","x":"כשיש עוקבים ויש עניין, זכויות השידור והחסויות הופכות רלוונטיות. הרשתות הבינו את העניין הגובר והחלו להילחם על זכויות השידור לאירועי ספורט הנשים השונים. בשלב הזה הקהל רק הלך וגדל בקצב שבעבר ספורטאיות יכלו רק לחלום עליו. ד\"ר פודקמיין בשיחה עם נועה הודתה כי \"המיתוג האישי של הספורטאיות הוא רלוונטי, לא רק המיתוג של הענף\" והמשיכה וציינה כי \"העניין של מיתוג אישי בישראל לא קורה והוא יכול לקרות. לספורטאיות יש תוכן ותוכן מעניין, על המשחקים, הישגים וכו', לכן השינוי יכול לבוא מהן.\" היא מוסיפה. בתגובה שיתפה כי \"הטענה בשטח היא שאנחנו ספורטאיות ואנחנו לא צריכות להתעסק בשיווק של עצמנו, אלא בהכנה לאימון או למשחק ובחיים הספורטיביים\" טענה שהיא על פניו לגיטימית, אבל לוקחת אותנו חזרה לשאלת הביצה והתרנגולת."},{"t":"p","x":"הדבר השני שקרה היה התמקדות בספורטאיות כוכבות בולטות על ידי הבאת הסיפורים האישיים שלהן וחשיפת ההישגים שלהן על מנת ללכוד את תשומת הלב של התקשורת והמעריצים. משווקים התחילו להתמקד בסיפורים האישיים של הספורטאיות, איך הן התגברו על מצוקות, על התשוקה שלהן לספורט ועל המסע שלהן להצלחה. זה חיבר את הספורטאיות לקהל רחב והפך אותן ליותר מעוררות השראה. סיפורים כמו זה של המתעמלת סימון ביילס, או האחיות וויליאמס בטניס; דמות צבעונית כמו הכדורגלנית (לשעבר) מייגן רפינו, או הכדורסלנית קייטלין קלארק שקולעת מהלוגו וממלאת אולמות. הקהל התחבר והצביע ברגליים."},{"t":"p","x":"פתאום, מותגים גדולים כמו נייקי, אדידס, או אנדרארמור רוצים להיות חלק מהסיפור, חלק מההצלחה. הנראות והשיווק של הספורטאיות פתאום הפך לעניין - מי ישים ידו על הפרס? ואם על ביצה או תרנגולת דיברנו, הפעם הפרס הוא לא החסות, אלא הספורטאית עצמה. אם בעבר ספורטאיות היו רודפות אחרי חסויות, היום החסויות רודפות אחריהן. וככה זה צריך להיות."},{"t":"p","x":"השינוי השלישי שקרה הוא צורת הייצוג של הספורטאיות במדיה. אם בעבר הפרסום התמקד ביופי שלהן כנשים, היום הוא מתמקד בכוח, ביכולות ובמיומנויות האישיות שבגינן הן מצליחות כל אחת בתחומה. הכוח שלהן הוצג כעוצמה נשית, עם חשיפת האתגרים שעמדו בדרכן להצלחה. השפה של הפרסום השתנתה והחלה להתמקד בשבירת סטיראוטיפים מגדריים, ושינוי תפיסות חברתיות עמוקות. בשפת השיווק מדובר על \"חינוך שוק\". בפודקאסט מעלה ד\"ר פודקמיין את סוגיית חינוך השוק בחברה הישראלית כשהיא שואלת את השאלה \"האם זה נשי לצרוך ספורט?\". שהרי אם זה לא נשי לצרוך ספורט, ברמה התפיסתית, על אחת כמה וכמה שזה לא נשי לעסוק בספורט."},{"t":"p","x":"השינוי התפיסתי העולמי שהחל ברמת הספורטאית הבודדת, המיתוג האישי אם תרצו, ייצר כדור שלג שהיום ממלא איצטדיונים וסוחף מליוני עוקבות ועוקבים אחרי ספורט נשים, השכר של השחקניות עלה (גם אם הוא עדיין רחוק מזה של הגברים), שלא לדבר על הרווחים מחסויות למיניהן. אז למה אנחנו לא מצליחות לעלות על הגל בזירה המקומית? למה הספורטאיות שלנו מעדיפות להיות הביצה ולא התרנגולת? ובכלל, כשהיציאים מלאים, המשכורות עולות ומגיעות החסויות, מישהי בכלל זוכרת מי באה קודם?"}]},"שמונה-נרות-של-חנוכה":{"b":[{"t":"p","x":"השנה האחרונה הייתה שנה מאתגרת ברמה הלאומית, אבל דווקא בחושך אנחנו אוהבות לחפש את נקודות האור. אז קבלו שמונה ספורטאיות שהאירו לנו את השנה האחרונה בתקווה והשראה:"},{"t":"p","x":"**נר ראשון, מורן סמואל** - החותרת הפראלימפית בת 42 הגיעה למשחקים האולימפיים בתקופה לא פשוטה עבורה, כשברקע היא מתמודדת עם אתגרים משפחתיים לצד קולות המלחמה בארץ. אבל מורן היא ספורטאית מנוסה, שהבינה שיש לה פה הזדמנות להראות את הכוח האמיתי שלה ושל העם כולו ועשתה זאת בגדול עם מדליית זהב במקצה החתירה ל-2000 מטרים במשחקים הפראלימפיים בפריז. סמואל, אמא לשלושה, הדליקה את האור והביאה המון גאווה לכולנו עם שירת התקווה על הפודיום בפריז. תודה מורן!"},{"t":"p","x":"**נר שני, נבחרת ישראל בכדורשער** - נבחרת הכדורשער של ישראל הביאה המון כבוד במשחקים הפראלימפיים בפריז עם מדלית כסף הסטורית בענף. הבנות ניצחו בחצי הגמר את הסיניות בתוצאה 2-1 מה שהפתיע רבים, אבל לא אותן- הן ידעו מה הן שוות ורצו ללכת על כל הקופה. לצערינו בגמר חיכתה האלופה טורקיה והבנות שלנו בכחול לבן רשמו הישג היסטורי עם מדלית הכסף. את התקווה הן השמיעו לאחר מכן בכפר האולימפי. בנות, אתן אלופות ואנחנו גאות בכן!"},{"t":"p","x":"**נר שלישי, שרון קנטור** - 2024 הייתה שנה מיוחדת עבור השייטת בת ה-21. קנטור שקטפה את תואר אלופת העולם מוקדם יותר השנה, הגיעה לפריז והשלימה את השנה עם מדליית כסף אולימפית. הזכייה האולימפית של שרון הפכה אותה לשייטת הישראלית הראשונה שזוכה במדליה אולימפית. אבל אותה זה לא מספק, היא רוצה יותר וכבר הכריזה שהמטרה שלה באולימפיאדת 2028 היא מדלית הזהב. אנחנו כמובן מאחוריה ומקוות שעוד הרבה ילדות ישראליות יקבלו ממנה השראה וילכו אחרי החלומות שלהן בכל הכוח. תודה שרון שהדלקת לנו עוד אור השנה!"},{"t":"p","x":"**נר רביעי, רז הרשקו **- זה כבר לא סוד שרז הרשקו היא ספורטאית מדהימה, אבל 2024 הייתה שנה מוצלחת במיוחד עבור הג'ודוקא שלנו. רז סיימה את השנה עם מדליית זהב באליפות אירופה ומדליית כסף במשחקים האולימפיים בפריז. למשחקים האולימפיים הרשקו הגיעה מדורגת שניה בעולם בקטגוריית המשקל שלה. בחצי הגמר היא עלתה חדה וסיימה לאחר 15 שניות בלבד בניצחון מוחץ על הטורקיה מה שהבטיח לה מקום בגמר האולימפי. בגמר היא אמנם הפסידה לברזילאית, אבל סחפה אחריה אומה שלמה וריגשה את כולנו כאשר קיבלה את מדלית הכסף מיעל ארד. רז, תודה שהדלקת לנו אור ועוד אור השנה!"},{"t":"p","x":"**נר חמישי נבחרת ישראל בהתעמלות אומנותית** - 2024 הייתה שנה מוצלחת ביותר עבור הנבחרת שזכתה במדלית הזהב בקרב-רב בגביע העולם בסופיה מוקדם יותר השנה והשלימה את ההישג המרשים עם מדלית כסף אולימפית. בשלב המוקדמות הגיעו הבנות למקום השישי והמכובד, מה ששמר להם מקום בגמר אותו סיימו במקום השני עם מדליה היסטורית. כל הכבוד בנות!"},{"t":"p","x":"**נר שישי, ענבר לניר** - אלופת העולם מ-2023 המשיכה לקטוף מדליות גם ב-2024 ונראה שהיא לא מתכוונת לעצור. הג'ודוקא בת ה-24 התחילה מזכיה במדליית הארד באליפות אירופה שהיוותה את הסיפתח למדליית הכסף האולימפית בה זכתה בפריז. לניר, שהדליקה אור גדול על מזרן הג'ודו לקחה צעד אחד מחוצה לו כשפתחה שיח חשוב על דימוי גוף כספורטאית וכאישה. ענבר הביאה לקדמת הבמה נושא רגיש והפכה את האור הגדול שהביאו ההישגים שלה בזירה הספורטיבית לאור גדול להרבה נשים וילדות צעירות. ענבר, אנחנו גאות בך, תודה!"},{"t":"p","x":"**נר שביעי, לונה צ'מטאי סלפטר** - עבור המרטוניסטית שלנו 2024 הייתה שנה מאתגרת. לונה נפצעה במרתון טוקיו בתחילת השנה ונדרשה לתקופת החלמה ארוכה. למרות זאת, היא הצליחה להגיע לאליפות אירופה בחצי מרתון בחודש יולי ולסיים במקום העשירי והמכובד. את ההישג המרשים היא המשיכה במשחקים האולימפיים בפריז כאשר סיימה במקום התשיעי בריצת המרתון - מיקום שיא עבור ישראלית בריצת המרתון באולימפיאדה. ההישג המרשים וההיסטורי של לונה הוא גאווה גדולה עבור כולנו וסמל לנחישות. לונה, את אלופה!"},{"t":"p","x":"**נר שמיני, אנסטסיה גורבנקו** - איזו שנה זו הייתה עבור השחיינית החיפאית בת ה-21. אמנם האולימפיאדה הסתיימה בטעם קצת מר, אבל האמת היא שבשנה הזו היו גורבנקו הישגים מרשימים שהביאו גאווה וגרמו להמנון התקווה להתנגן לא פעם ולא פעמיים (וגם לא שלוש…) בעולם. השנה המדהימה של אנסטסיה כללה זכייה במדליית הכסף במקצה ל-400 מטרים מעורב אישי באליפות העולם שנערכה בדוחה, מדליית זהב ב-200 ו-400 מעורב באליפות אירופה שנערכה בבלגרד, ושתי מדליות זהב קבוצתיות. ספרתן? תנו לנו לעזור לכן, אנחנו מדברות פה על 4 מדליות זהב באליפות אירופה ומדליית כסף אחת באליפות העולם. שנה מוצלחת בכל קנה מידה. תודה על כל האור שהדלקת לנו השנה, את אלופה!"},{"t":"p","x":"אז נכון, השנה הזו הייתה מאתגרת מהמון בחינות, אבל אנחנו גאות בכל הנשים המדהימות שהרימו את הראש מעבר, הסתכלו אל האופק והביאו תקווה לכולנו. תודה לכן, בזכותכן נדלקו פה עוד ועוד אורות השנה."}]}};
